(304919,33880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası kırmızı sağlık çantası sende. Birine ... Saygılar.'::text,'yardım edeceksin'::text,'yardım edeceksin'::text,NULL::text,'Açıkçası kırmızı sağlık çantası sende. Birine yardım edeceksin Saygılar.'::text),
