(304923,33881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, deine Sanitäterjacke ist ... als mein Mantel.'::text,'leuchtender'::text,'leuchtender'::text,'am leuchtendsten'::text,'Mal ehrlich, deine Sanitäterjacke ist leuchtender als mein Mantel.'::text),
(304927,33881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, твоя медична куртка ... за моє пальто.'::text,'яскравіша'::text,'більш яскрава'::text,'найяскравіша'::text,'Не буду брехати, твоя медична куртка яскравіша за моє пальто.'::text),
