(328620,36514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Total schockierend! Sie ist nicht ... als er, aber sie trifft!'::text,'jünger'::text,'jünger'::text,'am jüngsten'::text,'Total schockierend! Sie ist nicht jünger als er, aber sie trifft!'::text),
(328624,36514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто шок! Вона не ... за нього, але забиває!'::text,'молодша'::text,'більш молода'::text,'наймолодша'::text,'Просто шок! Вона не молодша за нього, але забиває!'::text),
(328623,36514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué fuerte! Ella no es ... que él, ¡pero encesta!'::text,'más joven'::text,'más joven'::text,'la más joven'::text,'¡Qué fuerte! Ella no es más joven que él, ¡pero encesta!'::text),
(328622,36514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Complètement choquant ! Elle n''est pas ... que lui, mais elle marque !'::text,'plus jeune'::text,'plus jeune'::text,'la plus jeune'::text,'Complètement choquant ! Elle n''est pas plus jeune que lui, mais elle marque !'::text),
(328625,36514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen şok! O, ondan ... değil ama sayı atıyor!'::text,'daha genç'::text,'daha genç'::text,'en genç'::text,'Resmen şok! O, ondan daha genç değil ama sayı atıyor!'::text),
(328626,36514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen sokkoló! Nem ... nála, mégis betalál!'::text,'fiatalabb'::text,'fiatalabb'::text,'legfiatalabb'::text,'Teljesen sokkoló! Nem fiatalabb nála, mégis betalál!'::text),
