(328653,36517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy a fiatal srác ... nevetett az egész meccsen.'::text,'boldogan'::text,'boldog'::text,'boldogság'::text,'Szóval azt mondta, hogy a fiatal srác boldogan nevetett az egész meccsen.'::text),
(310872,34542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie besichtigt zwei Wohnungen mit zwei unterschiedlichen ...'::text,'Preisen.'::text,'Preis.'::text,'Preisen.'::text,'Sie besichtigt zwei Wohnungen mit zwei unterschiedlichen Preisen.'::text),
(310876,34542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона дивиться дві квартири з двома різними ...'::text,'цінами.'::text,'ціною.'::text,'цінами.'::text,'Вона дивиться дві квартири з двома різними цінами.'::text),
(310875,34542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella mira dos pisos con dos ... distintos.'::text,'precios'::text,'precio'::text,'precios'::text,'Ella mira dos pisos con dos precios distintos.'::text),
(310874,34542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle visite deux appartements avec deux ... différents.'::text,'prix'::text,'prix'::text,'prix'::text,'Elle visite deux appartements avec deux prix différents.'::text),
(310877,34542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki daireye bakıyor ve iki farklı ... var.'::text,'fiyat'::text,'fiyat'::text,'fiyatlar'::text,'İki daireye bakıyor ve iki farklı fiyat var.'::text),
(310878,34542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két lakást néz meg két különböző ...'::text,'árral.'::text,'árral.'::text,'árral.'::text,'Két lakást néz meg két különböző árral.'::text),
(310881,34543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Preis der großen Glaswohnung beträgt 10.000 Euro.'::text,'Der'::text,'Ein'::text,'Ein'::text,'Der Preis der großen Glaswohnung beträgt 10.000 Euro.'::text),
(310885,34543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ціна великої скляної квартири — 10 000 євро.'::text,''::text,NULL::text,NULL::text,'Ціна великої скляної квартири — 10 000 євро.'::text),
(310884,34543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... precio del gran piso de cristal es de 10 000 euros.'::text,'El'::text,'Un'::text,'Un'::text,'El precio del gran piso de cristal es de 10 000 euros.'::text),
(310883,34543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... prix du grand appartement vitré est de 10 000 euros.'::text,'Le'::text,'Un'::text,'Un'::text,'Le prix du grand appartement vitré est de 10 000 euros.'::text),
(310886,34543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük cam dairenin ... fiyatı 10.000 euro.'::text,''::text,'bir'::text,'bir'::text,'Büyük cam dairenin fiyatı 10.000 euro.'::text),
(310887,34543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... nagy üveglakás ára 10 000 euró.'::text,'A'::text,'Egy'::text,'Egy'::text,'A nagy üveglakás ára 10 000 euró.'::text),
(310890,34544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! ... Preis ist 10.000 Euro! Unglaublich!'::text,'Jener'::text,'Jene'::text,'Diese'::text,'Nein! Jener Preis ist 10.000 Euro! Unglaublich!'::text),
(310894,34544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! ... ціна — 10 000 євро! Неймовірно!'::text,'Та'::text,'Ті'::text,'Ці'::text,'Ні! Та ціна — 10 000 євро! Неймовірно!'::text),
(310893,34544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡... precio es de 10 000 euros! ¡Increíble!'::text,'Ese'::text,'Esos'::text,'Estos'::text,'¡No! ¡Ese precio es de 10 000 euros! ¡Increíble!'::text),
(310892,34544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! ... prix est de 10 000 euros ! Incroyable !'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Non ! Ce prix est de 10 000 euros ! Incroyable !'::text),
(310895,34544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! ... fiyat 10.000 euro! İnanılmaz!'::text,'Şu'::text,'Şu'::text,'Bu'::text,'Hayır! Şu fiyat 10.000 euro! İnanılmaz!'::text),
(310896,34544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! ... az ár 10 000 euró! Hihetetlen!'::text,'Az'::text,'Azok'::text,'Ezek'::text,'Ne! Az az ár 10 000 euró! Hihetetlen!'::text),
(310899,34545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Die Wohnung ist schön, aber ... Preis ist furchtbar!'::text,'ihr'::text,'es ist'::text,'sein'::text,'Albtraum! Die Wohnung ist schön, aber ihr Preis ist furchtbar!'::text),
(310903,34545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Квартира гарна, але ... ціна жахлива!'::text,'її'::text,'це є'::text,'його'::text,'Жах! Квартира гарна, але її ціна жахлива!'::text),
(310902,34545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué pesadilla! El piso está bien, ¡pero ... precio es horrible!'::text,'su'::text,'es'::text,'su'::text,'¡Qué pesadilla! El piso está bien, ¡pero su precio es horrible!'::text),
(310901,34545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! L''appartement est beau, mais ... prix est horrible !'::text,'son'::text,'c''est'::text,'son'::text,'Cauchemar ! L''appartement est beau, mais son prix est horrible !'::text),
(310904,34545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Daire güzel ama ... fiyatı berbat!'::text,'onun'::text,'o'::text,'onun'::text,'Kâbus! Daire güzel ama onun fiyatı berbat!'::text),
(310905,34545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A lakás szép, de ... borzasztó!'::text,'az ára'::text,'ez'::text,'az ára'::text,'Rémálom! A lakás szép, de az ára borzasztó!'::text),
(310908,34546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Preis erscheint ... dem Bildschirm über ihr.'::text,'auf'::text,'in'::text,'an'::text,'Der Preis erscheint auf dem Bildschirm über ihr.'::text),
(310912,34546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціна з''являється ... екрані над нею.'::text,'на'::text,'у'::text,'біля'::text,'Ціна з''являється на екрані над нею.'::text),
(310911,34546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El precio aparece ... la pantalla que hay encima de ella.'::text,'en'::text,'en'::text,'a'::text,'El precio aparece en la pantalla que hay encima de ella.'::text),
(310910,34546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le prix apparaît ... l''écran au-dessus d''elle.'::text,'sur'::text,'dans'::text,'à'::text,'Le prix apparaît sur l''écran au-dessus d''elle.'::text),
(310913,34546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fiyat, üstündeki ekranın ... beliriyor.'::text,'üzerinde'::text,'içinde'::text,NULL::text,'Fiyat, üstündeki ekranın üzerinde beliriyor.'::text),
(310914,34546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ár a fölötte lévő ... jelenik meg.'::text,'képernyőn'::text,'képernyőben'::text,'képernyőnél'::text,'Az ár a fölötte lévő képernyőn jelenik meg.'::text),
(310935,34549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für ein Schnäppchen, na klar. Da ... zwei Preise, und beide sind riesig.'::text,'sind'::text,'ist'::text,'sein'::text,'Was für ein Schnäppchen, na klar. Da sind zwei Preise, und beide sind riesig.'::text),
(310939,34549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яка вигідна покупка, звісно. Тут ... дві ціни, і обидві величезні.'::text,'є'::text,'є'::text,'бути'::text,'Яка вигідна покупка, звісно. Тут є дві ціни, і обидві величезні.'::text),
(310938,34549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué ganga, obviamente. ... dos precios, y los dos son enormes.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Qué ganga, obviamente. Hay dos precios, y los dos son enormes.'::text),
(310937,34549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelle affaire, évidemment. ... deux prix, et les deux sont énormes.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Quelle affaire, évidemment. Il y a deux prix, et les deux sont énormes.'::text),
(310940,34549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kelepir ama, belli ki. İki fiyat ... ve ikisi de çok yüksek.'::text,'var'::text,'var'::text,'olmak'::text,'Ne kelepir ama, belli ki. İki fiyat var ve ikisi de çok yüksek.'::text),
(310941,34549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda alku, nyilván. Két ár ..., és mindkettő óriási.'::text,'van'::text,'van'::text,'lenni'::text,'Micsoda alku, nyilván. Két ár van, és mindkettő óriási.'::text),
(318378,35376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... so reumütig, und die Tulpen sind ein cooler Move.'::text,'bist'::text,'ist'::text,'bin'::text,'Du bist so reumütig, und die Tulpen sind ein cooler Move.'::text),
(318382,35376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... такий винуватий, і тюльпани — крутий хід.'::text,'є'::text,'є'::text,'є'::text,'Ти є такий винуватий, і тюльпани — крутий хід.'::text),
(318381,35376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... muy arrepentido, y los tulipanes son un detalle guay.'::text,'estás'::text,'está'::text,'estoy'::text,'Tú estás muy arrepentido, y los tulipanes son un detalle guay.'::text),
(318380,35376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... tellement désolé, et les tulipes, c''est un geste cool.'::text,'es'::text,'est'::text,'suis'::text,'Tu es tellement désolé, et les tulipes, c''est un geste cool.'::text),
(318383,35376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen çok pişman ... ve laleler de havalı bir hamle.'::text,''::text,NULL::text,NULL::text,'Sen çok pişman ve laleler de havalı bir hamle.'::text),
(318384,35376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te annyira bűnbánó ..., és a tulipánok menő húzás.'::text,'vagy'::text,NULL::text,'vagyok'::text,'Te annyira bűnbánó vagy, és a tulipánok menő húzás.'::text),
(318396,35378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es tut ihm leid. ... er den Laptop retten?'::text,'Kann'::text,'Ist'::text,'Hat'::text,'Es tut ihm leid. Kann er den Laptop retten?'::text),
(318400,35378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому шкода. Чи ... він урятувати ноутбук?'::text,'може'::text,'є'::text,'має'::text,'Йому шкода. Чи може він урятувати ноутбук?'::text),
(318399,35378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lo siente. ¿... salvar el portátil?'::text,'Puede'::text,'Está'::text,'Tiene'::text,'Lo siente. ¿Puede salvar el portátil?'::text),
(318398,35378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est désolé. Est-ce qu''il ... sauver l''ordinateur portable ?'::text,'peut'::text,'est'::text,'a'::text,'Il est désolé. Est-ce qu''il peut sauver l''ordinateur portable ?'::text),
(318401,35378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üzgün. Dizüstü bilgisayarı ... mi?'::text,'kurtarabilir'::text,NULL::text,NULL::text,'Üzgün. Dizüstü bilgisayarı kurtarabilir mi?'::text),
(318402,35378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sajnálja. ... megmenteni a laptopot?'::text,'Tudja'::text,'Van'::text,'Van neki'::text,'Sajnálja. Tudja megmenteni a laptopot?'::text),
(318405,35379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tut es ihm leid? Der Laptop ist voller Kaffee.'::text,'Warum'::text,'Wer'::text,'Wo'::text,'Warum tut es ihm leid? Der Laptop ist voller Kaffee.'::text),
(318409,35379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... йому шкода? Ноутбук увесь у каві.'::text,'Чому'::text,'Хто'::text,'Де'::text,'Чому йому шкода? Ноутбук увесь у каві.'::text),
(318408,35379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... lo siente? El portátil está lleno de café.'::text,'Por qué'::text,'Quién'::text,'Dónde'::text,'¿Por qué lo siente? El portátil está lleno de café.'::text),
(318407,35379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est-il désolé ? L''ordinateur portable est plein de café.'::text,'Pourquoi'::text,'Qui'::text,'Où'::text,'Pourquoi est-il désolé ? L''ordinateur portable est plein de café.'::text),
(318410,35379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... üzgün? Dizüstü bilgisayar kahveyle dolu.'::text,'Neden'::text,'Kim'::text,'Nerede'::text,'Neden üzgün? Dizüstü bilgisayar kahveyle dolu.'::text),
(318411,35379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sajnálja? A laptop tele van kávéval.'::text,'Miért'::text,'Ki'::text,'Hol'::text,'Miért sajnálja? A laptop tele van kávéval.'::text),
(318414,35380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es tat ihm leid, also ... er Tulpen für seine Kollegin.'::text,'kaufte'::text,'kauft'::text,'kaufte'::text,'Es tat ihm leid, also kaufte er Tulpen für seine Kollegin.'::text),
(318418,35380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому було шкода, тож він ... тюльпани для колеги.'::text,'купив'::text,'купує'::text,'купив'::text,'Йому було шкода, тож він купив тюльпани для колеги.'::text),
(318417,35380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lo sentía, así que ... tulipanes para su compañera.'::text,'compró'::text,'compra'::text,'compró'::text,'Lo sentía, así que compró tulipanes para su compañera.'::text),
(318416,35380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il était désolé, alors il ... des tulipes pour sa collègue.'::text,'a acheté'::text,'achète'::text,'a acheté'::text,'Il était désolé, alors il a acheté des tulipes pour sa collègue.'::text),
(318419,35380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üzgündü, bu yüzden iş arkadaşı için lale ...'::text,'aldı'::text,'alır'::text,'aldı'::text,'Üzgündü, bu yüzden iş arkadaşı için lale aldı.'::text),
(318420,35380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sajnálta, ezért tulipánt ... a kolléganőjének.'::text,'vett'::text,'vesz'::text,'vett'::text,'Sajnálta, ezért tulipánt vett a kolléganőjének.'::text),
(318432,35382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, er hat sich ... bei ihr entschuldigt.'::text,'höflich'::text,'höflich'::text,'Höflichkeit'::text,'Rate mal, ich hab gehört, er hat sich höflich bei ihr entschuldigt.'::text),
(318436,35382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що він ... вибачився перед нею.'::text,'ввічливо'::text,'ввічливий'::text,'ввічливість'::text,'Уяви, я чула, що він ввічливо вибачився перед нею.'::text),
(318435,35382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, me han dicho que le pidió perdón ...'::text,'educadamente'::text,'educado'::text,'educación'::text,'Adivina qué, me han dicho que le pidió perdón educadamente.'::text),
(318434,35382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu dire qu''il s''est excusé ... auprès d''elle.'::text,'poliment'::text,'poli'::text,'politesse'::text,'Devine quoi, j''ai entendu dire qu''il s''est excusé poliment auprès d''elle.'::text),
(318437,35382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, duydum ki ondan ... özür dilemiş.'::text,'kibarca'::text,'kibar'::text,'kibarlık'::text,'Tahmin et ne oldu, duydum ki ondan kibarca özür dilemiş.'::text),
(318438,35382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy ... bocsánatot kért tőle.'::text,'udvariasan'::text,'udvarias'::text,'udvariasság'::text,'Képzeld, azt hallottam, hogy udvariasan bocsánatot kért tőle.'::text),
(318441,35383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, es tat ihm leid, ... hat er ihr Tulpen gekauft.'::text,'also'::text,'aber'::text,'weil'::text,'Hör zu, ich hab gehört, es tat ihm leid, also hat er ihr Tulpen gekauft.'::text),
(318445,35383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що йому було шкода, ... він купив їй тюльпани.'::text,'тому'::text,'але'::text,'бо'::text,'Слухай, я чула, що йому було шкода, тому він купив їй тюльпани.'::text),
(318444,35383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que lo sentía, ... le compró tulipanes.'::text,'así que'::text,'pero'::text,'porque'::text,'Oye, me han dicho que lo sentía, así que le compró tulipanes.'::text),
(318443,35383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''il était désolé, ... il lui a acheté des tulipes.'::text,'donc'::text,'mais'::text,'parce que'::text,'Écoute, j''ai entendu dire qu''il était désolé, donc il lui a acheté des tulipes.'::text),
(318446,35383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki üzgünmüş, ... ona lale almış.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Dinle, duydum ki üzgünmüş, bu yüzden ona lale almış.'::text),
(318447,35383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy sajnálta, ... tulipánt vett neki.'::text,'ezért'::text,'de'::text,'mert'::text,'Figyelj, azt hallottam, hogy sajnálta, ezért tulipánt vett neki.'::text),
(296238,32916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Ledersessel ist ... altes Möbelstück.'::text,'ein'::text,'ein'::text,'das'::text,'Der Ledersessel ist ein altes Möbelstück.'::text),
(296242,32916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шкіряне крісло — це ... старий предмет меблів.'::text,''::text,NULL::text,NULL::text,'Шкіряне крісло — це старий предмет меблів.'::text),
(296241,32916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sillón de cuero es ... mueble antiguo.'::text,'un'::text,'un'::text,'el'::text,'El sillón de cuero es un mueble antiguo.'::text),
(296240,32916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fauteuil en cuir est ... vieux meuble.'::text,'un'::text,'un'::text,'le'::text,'Le fauteuil en cuir est un vieux meuble.'::text),
(296243,32916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deri koltuk ... eski mobilya parçası.'::text,'bir'::text,'bir'::text,NULL::text,'Deri koltuk bir eski mobilya parçası.'::text),
(296244,32916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bőrfotel ... régi bútordarab.'::text,'egy'::text,'egy'::text,'a'::text,'A bőrfotel egy régi bútordarab.'::text),
