(296260,32918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літній чоловік обожнює ... меблі — велике шкіряне крісло.'::text,'свої'::text,'свої'::text,'свої'::text,'Літній чоловік обожнює свої меблі — велике шкіряне крісло.'::text),
