(296261,32918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam ... mobilyasını, büyük deri koltuğu çok seviyor.'::text,'onun'::text,'onun'::text,'onların'::text,'Yaşlı adam onun mobilyasını, büyük deri koltuğu çok seviyor.'::text),
(296262,32918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idősebb férfi imádja a ..., egy nagy bőrfotelt.'::text,'bútorát'::text,'bútorát'::text,'bútorukat'::text,'Az idősebb férfi imádja a bútorát, egy nagy bőrfotelt.'::text),
(296265,32919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau sitzt ... einem großen Sofa, ihrem Lieblingsmöbel.'::text,'auf'::text,'an'::text,'unter'::text,'Die Frau sitzt auf einem großen Sofa, ihrem Lieblingsmöbel.'::text),
(296269,32919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка сидить ... великому дивані, своєму улюбленому предметі меблів.'::text,'на'::text,'біля'::text,'під'::text,'Жінка сидить на великому дивані, своєму улюбленому предметі меблів.'::text),
(296268,32919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer se sienta ... un sofá grande, su mueble favorito.'::text,'en'::text,'a'::text,'debajo de'::text,'La mujer se sienta en un sofá grande, su mueble favorito.'::text),
(296267,32919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme s''assoit ... un grand canapé, son meuble préféré.'::text,'sur'::text,'à'::text,'sous'::text,'La femme s''assoit sur un grand canapé, son meuble préféré.'::text),
(296270,32919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın en sevdiği mobilya olan büyük bir kanepenin ... oturuyor.'::text,'üstüne'::text,NULL::text,'altına'::text,'Kadın en sevdiği mobilya olan büyük bir kanepenin üstüne oturuyor.'::text),
(296271,32919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő egy nagy ... ül, a kedvenc bútorán.'::text,'kanapén'::text,'kanapénál'::text,'kanapé alatt'::text,'A nő egy nagy kanapén ül, a kedvenc bútorán.'::text),
(296283,32921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast echt schöne ... in diesem Zimmer.'::text,'Möbel'::text,'Möbel'::text,'ein Möbelstück'::text,'Ehrlich, du hast echt schöne Möbel in diesem Zimmer.'::text),
(296287,32921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у тебе чудові ... в цій кімнаті.'::text,'меблі'::text,'меблі'::text,'меблі'::text,'Чесно, у тебе чудові меблі в цій кімнаті.'::text),
(296286,32921,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, qué ... tan bonito tienes en esta habitación.'::text,'mobiliario'::text,'mobiliario'::text,'un mueble'::text,'En serio, qué mobiliario tan bonito tienes en esta habitación.'::text),
(296285,32921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as de très beaux ... dans cette pièce.'::text,'meubles'::text,'meubles'::text,'un meuble'::text,'Franchement, tu as de très beaux meubles dans cette pièce.'::text),
(296288,32921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bu odada çok güzel ... var.'::text,'mobilya'::text,'mobilyalar'::text,'bir mobilya'::text,'Açıkçası bu odada çok güzel mobilya var.'::text),
(296289,32921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, gyönyörű ... van ebben a szobában.'::text,'bútorod'::text,'bútorod'::text,'egy bútorod'::text,'Őszintén, gyönyörű bútorod van ebben a szobában.'::text),
(296301,32923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im hellen Wohnzimmer ... jede Menge Mobiliar.'::text,'ist'::text,'sind'::text,'sein'::text,'Im hellen Wohnzimmer ist jede Menge Mobiliar.'::text),
