(296304,32923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... muchos muebles en el salón luminoso.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay muchos muebles en el salón luminoso.'::text),
(296303,32923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... beaucoup de meubles dans le salon lumineux.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a beaucoup de meubles dans le salon lumineux.'::text),
(296306,32923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aydınlık oturma odasında çok mobilya ...'::text,'var'::text,'var'::text,'olmak'::text,'Aydınlık oturma odasında çok mobilya var.'::text),
(296307,32923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A világos nappaliban sok bútor ...'::text,'van'::text,'van'::text,'lenni'::text,'A világos nappaliban sok bútor van.'::text),
(304635,33849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stark! Du ... einen tollen Marsch und coole weiße Handschuhe.'::text,'hast'::text,'hat'::text,'hast'::text,'Stark! Du hast einen tollen Marsch und coole weiße Handschuhe.'::text),
(304639,33849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круто! Ти ... класний марш і круті білі рукавички.'::text,'маєш'::text,'має'::text,'маєш'::text,'Круто! Ти маєш класний марш і круті білі рукавички.'::text),
(304638,33849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué estilo! ... una marcha genial y unos guantes blancos guays.'::text,'Tienes'::text,'Tiene'::text,'Tienes'::text,'¡Qué estilo! Tienes una marcha genial y unos guantes blancos guays.'::text),
(304637,33849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trop classe ! Tu ... un super défilé et des gants blancs cool.'::text,'as'::text,'a'::text,'as'::text,'Trop classe ! Tu as un super défilé et des gants blancs cool.'::text),
(304640,33849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok şık! Harika bir tören yürüyüşün ve havalı beyaz eldivenlerin ...'::text,'var'::text,'var'::text,'var'::text,'Çok şık! Harika bir tören yürüyüşün ve havalı beyaz eldivenlerin var.'::text),
(304641,33849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stílusos! Neked ... egy szuper meneted és menő fehér kesztyűd.'::text,'van'::text,'van'::text,'van'::text,'Stílusos! Neked van egy szuper meneted és menő fehér kesztyűd.'::text),
(304644,33850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Marsch ist echt ikonisch, und deine schwarzen ... sind so sauber.'::text,'Stiefel'::text,'Stiefel'::text,'Stiefel'::text,'Dein Marsch ist echt ikonisch, und deine schwarzen Stiefel sind so sauber.'::text),
(304648,33850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твій марш, чесно, культовий, а твої чорні ... такі чисті.'::text,'черевики'::text,'черевик'::text,'черевики'::text,'Твій марш, чесно, культовий, а твої чорні черевики такі чисті.'::text),
(304647,33850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu marcha es icónica, en serio, y tus ... negras están impecables.'::text,'botas'::text,'bota'::text,'botas'::text,'Tu marcha es icónica, en serio, y tus botas negras están impecables.'::text),
(304646,33850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton défilé est culte, franchement, et tes ... noires sont si propres.'::text,'bottes'::text,'botte'::text,'bottes'::text,'Ton défilé est culte, franchement, et tes bottes noires sont si propres.'::text),
(304649,33850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşün gerçekten ikonik ve siyah ... çok temiz.'::text,'botların'::text,'botun'::text,'botların'::text,'Yürüyüşün gerçekten ikonik ve siyah botların çok temiz.'::text),
(304650,33850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A meneteléd őszintén ikonikus, és a fekete ... olyan tiszták.'::text,'csizmáid'::text,'csizmád'::text,'csizmáid'::text,'A meneteléd őszintén ikonikus, és a fekete csizmáid olyan tiszták.'::text),
(304662,33852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Marsch findet auf einer breiten Straße in der Stadt statt.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Marsch findet auf einer breiten Straße in der Stadt statt.'::text),
(304666,33852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... марш відбувається на широкій міській вулиці.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей марш відбувається на широкій міській вулиці.'::text),
(304665,33852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... desfile es en una calle ancha de la ciudad.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este desfile es en una calle ancha de la ciudad.'::text),
(304664,33852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... défilé a lieu dans une large rue de la ville.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce défilé a lieu dans une large rue de la ville.'::text),
(304667,33852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yürüyüş geniş bir şehir caddesinde.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu yürüyüş geniş bir şehir caddesinde.'::text),
