(304680,33854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'An der Spitze des Marsches ... Trommler.'::text,'sind'::text,'ist'::text,'sein'::text,'An der Spitze des Marsches sind Trommler.'::text),
(304684,33854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На чолі маршу ... барабанщики.'::text,'є'::text,'є'::text,'бути'::text,'На чолі маршу є барабанщики.'::text),
(304683,33854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tamborileros al frente del desfile.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay tamborileros al frente del desfile.'::text),
(304682,33854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des tambours en tête du défilé.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des tambours en tête du défilé.'::text),
(304685,33854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşün önünde davulcular ...'::text,'var'::text,'var'::text,'olmak'::text,'Yürüyüşün önünde davulcular var.'::text),
(304686,33854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A menet élén dobosok ...'::text,'vannak'::text,'van'::text,'lenni'::text,'A menet élén dobosok vannak.'::text),
(304689,33855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei einem Marsch ... die Kadetten im Gleichschritt gehen.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Bei einem Marsch sollten die Kadetten im Gleichschritt gehen.'::text),
(304693,33855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під час маршу курсанти ... крокувати одночасно.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Під час маршу курсанти мали б крокувати одночасно.'::text),
(304692,33855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En un desfile, los cadetes ... marcar el paso a la vez.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'En un desfile, los cadetes deberían marcar el paso a la vez.'::text),
(304691,33855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans un défilé, les cadets ... marcher au pas en même temps.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'Dans un défilé, les cadets devraient marcher au pas en même temps.'::text),
(304694,33855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir tören yürüyüşünde harbiyeliler aynı anda adım ...'::text,'atmalı'::text,'atmalı'::text,'atmalı'::text,'Bir tören yürüyüşünde harbiyeliler aynı anda adım atmalı.'::text),
(304695,33855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy menetben a kadétoknak egyszerre ... lépniük.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Egy menetben a kadétoknak egyszerre kellene lépniük.'::text),
(304698,33856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unter uns, der Marsch war lang, ... anscheinend hat niemand aufgehört zu klatschen.'::text,'aber'::text,'weil'::text,'also'::text,'Unter uns, der Marsch war lang, aber anscheinend hat niemand aufgehört zu klatschen.'::text),
(304702,33856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, марш був довгий, ... начебто ніхто не переставав плескати.'::text,'але'::text,'бо'::text,'тому'::text,'Між нами, марш був довгий, але начебто ніхто не переставав плескати.'::text),
(304701,33856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nosotros, el desfile fue largo, ... al parecer nadie dejó de aplaudir.'::text,'pero'::text,'porque'::text,'así que'::text,'Entre nosotros, el desfile fue largo, pero al parecer nadie dejó de aplaudir.'::text),
(304700,33856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, le défilé était long, ... apparemment personne n''a arrêté d''applaudir.'::text,'mais'::text,'parce que'::text,'donc'::text,'Entre nous, le défilé était long, mais apparemment personne n''a arrêté d''applaudir.'::text),
(304703,33856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, yürüyüş uzundu ... görünüşe göre kimse alkışlamayı bırakmadı.'::text,'ama'::text,'çünkü'::text,'bu yüzden'::text,'Aramızda kalsın, yürüyüş uzundu ama görünüşe göre kimse alkışlamayı bırakmadı.'::text),
(304704,33856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köztünk szólva, a menet hosszú volt, ... állítólag senki nem hagyta abba a tapsot.'::text,'de'::text,'mert'::text,'ezért'::text,'Köztünk szólva, a menet hosszú volt, de állítólag senki nem hagyta abba a tapsot.'::text),
(301773,33531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kinder schreien vor Freude und ziehen an ... Händen.'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Die Kinder schreien vor Freude und ziehen an ihren Händen.'::text),
(301777,33531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Діти кричать від радості й тягнуть за ... руки.'::text,'її'::text,'його'::text,'його'::text,'Діти кричать від радості й тягнуть за її руки.'::text),
(301776,33531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los niños gritan de alegría y tiran de ... manos.'::text,'sus'::text,'sus'::text,'sus'::text,'Los niños gritan de alegría y tiran de sus manos.'::text),
(301775,33531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les enfants crient de joie et tirent sur ... mains.'::text,'ses'::text,'ses'::text,'ses'::text,'Les enfants crient de joie et tirent sur ses mains.'::text),
(301778,33531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuklar sevinçten çığlık atıyor ve ... ellerini çekiştiriyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Çocuklar sevinçten çığlık atıyor ve onun ellerini çekiştiriyor.'::text),
(301779,33531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyerekek örömükben sikoltoznak, és a ... húzzák.'::text,'kezét'::text,'kezét'::text,'kezét'::text,'A gyerekek örömükben sikoltoznak, és a kezét húzzák.'::text),
(301782,33532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Freude überall! Absolut alle tanzen ... Wohnzimmer!'::text,'im'::text,'auf dem'::text,'am'::text,'Freude überall! Absolut alle tanzen im Wohnzimmer!'::text),
(301786,33532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Радість усюди! Абсолютно всі танцюють ... вітальні!'::text,'у'::text,'на'::text,'біля'::text,'Радість усюди! Абсолютно всі танцюють у вітальні!'::text),
(301785,33532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Alegría por todas partes! ¡Absolutamente todo el mundo baila ... el salón!'::text,'en'::text,'sobre'::text,'a'::text,'¡Alegría por todas partes! ¡Absolutamente todo el mundo baila en el salón!'::text),
(301784,33532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La joie partout ! Absolument tout le monde danse ... le salon !'::text,'dans'::text,'sur'::text,'à'::text,'La joie partout ! Absolument tout le monde danse dans le salon !'::text),
(301787,33532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yerde neşe! İstisnasız herkes oturma odasında ... dans ediyor!'::text,''::text,'üstünde'::text,NULL::text,'Her yerde neşe! İstisnasız herkes oturma odasında dans ediyor!'::text),
(301788,33532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öröm mindenhol! Abszolút mindenki a ... táncol!'::text,'nappaliban'::text,'nappalin'::text,'nappalinál'::text,'Öröm mindenhol! Abszolút mindenki a nappaliban táncol!'::text),
(301800,33534,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... die Kids vor Freude, als sie ankam.'::text,'schrien'::text,'schreien'::text,'schrien'::text,'Bestie, anscheinend schrien die Kids vor Freude, als sie ankam.'::text),
(301804,33534,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, діти нібито ... від радості, коли вона прийшла.'::text,'кричали'::text,'кричать'::text,'кричали'::text,'Подружко, діти нібито кричали від радості, коли вона прийшла.'::text),
(301803,33534,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer los niños ... de alegría cuando llegó.'::text,'gritaron'::text,'gritan'::text,'gritaron'::text,'Tía, al parecer los niños gritaron de alegría cuando llegó.'::text),
(301802,33534,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment les enfants ... de joie quand elle est arrivée.'::text,'ont crié'::text,'crient'::text,'ont crié'::text,'Ma belle, apparemment les enfants ont crié de joie quand elle est arrivée.'::text),
(301805,33534,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, anlaşılan o geldiğinde çocuklar sevinçten ...'::text,'çığlık attı'::text,'çığlık atar'::text,'çığlık attı'::text,'Kankam, anlaşılan o geldiğinde çocuklar sevinçten çığlık attı.'::text),
(301806,33534,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a gyerekek ... örömükben, amikor megérkezett.'::text,'sikoltoztak'::text,'sikoltoznak'::text,'sikoltoztak'::text,'Csajszi, állítólag a gyerekek sikoltoztak örömükben, amikor megérkezett.'::text),
(301818,33536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, anscheinend ... gerade alle auf der Party vor Freude.'::text,'tanzen'::text,'tanzen'::text,'tanzen'::text,'Okay, anscheinend tanzen gerade alle auf der Party vor Freude.'::text),
(301822,33536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, усі саме зараз ... від радості на вечірці.'::text,'танцюють'::text,'танцюють'::text,'танцюють'::text,'Коротше, кажуть, усі саме зараз танцюють від радості на вечірці.'::text),
(301821,33536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ahora mismo todo el mundo ... de alegría en la fiesta.'::text,'está bailando'::text,'baila'::text,'está bailando'::text,'Vale, pues al parecer ahora mismo todo el mundo está bailando de alegría en la fiesta.'::text),
(301820,33536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment tout le monde ... de joie à la fête en ce moment.'::text,'est en train de danser'::text,'danse'::text,'est en train de danser'::text,'Bon, apparemment tout le monde est en train de danser de joie à la fête en ce moment.'::text),
(301823,33536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şöyle, anlaşılan şu an partide herkes sevinçten ...'::text,'dans ediyor'::text,'dans eder'::text,'dans ediyor'::text,'Şöyle, anlaşılan şu an partide herkes sevinçten dans ediyor.'::text),
(301824,33536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag most mindenki örömében ... a buliban.'::text,'táncol'::text,'táncol'::text,'táncol'::text,'Szóval állítólag most mindenki örömében táncol a buliban.'::text),
(301827,33537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine ruhige Party, na klar. Normalerweise sitzen die Leute, aber heute ... alle vor Freude.'::text,'tanzen'::text,'tanzen'::text,NULL::text,'Eine ruhige Party, na klar. Normalerweise sitzen die Leute, aber heute tanzen alle vor Freude.'::text),
(301831,33537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тиха вечірка, аякже. Зазвичай люди сидять, але сьогодні всі ... від радості.'::text,'танцюють'::text,'танцюють'::text,NULL::text,'Тиха вечірка, аякже. Зазвичай люди сидять, але сьогодні всі танцюють від радості.'::text),
(301830,33537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una fiesta tranquila, obviamente. La gente suele estar sentada, pero hoy todo el mundo ... de alegría.'::text,'está bailando'::text,'baila'::text,NULL::text,'Una fiesta tranquila, obviamente. La gente suele estar sentada, pero hoy todo el mundo está bailando de alegría.'::text),
(301829,33537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fête calme, évidemment. D''habitude, les gens restent assis, mais aujourd''hui tout le monde ... de joie.'::text,'est en train de danser'::text,'danse'::text,NULL::text,'Une fête calme, évidemment. D''habitude, les gens restent assis, mais aujourd''hui tout le monde est en train de danser de joie.'::text),
(301832,33537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakin bir parti, belli ki. İnsanlar genelde oturur ama bugün herkes sevinçten ...'::text,'dans ediyor'::text,'dans eder'::text,NULL::text,'Sakin bir parti, belli ki. İnsanlar genelde oturur ama bugün herkes sevinçten dans ediyor.'::text),
(301833,33537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csendes buli, nyilván. Az emberek általában ülnek, de ma mindenki örömében ...'::text,'táncol'::text,'táncol'::text,NULL::text,'Csendes buli, nyilván. Az emberek általában ülnek, de ma mindenki örömében táncol.'::text),
(301836,33538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Geschenke öffnen, ... die Kinder vor Freude schreien.'::text,'werden'::text,'schrien'::text,'schreiend'::text,'Wenn sie die Geschenke öffnen, werden die Kinder vor Freude schreien.'::text),
(301840,33538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони відкриють подарунки, діти ... від радості.'::text,'закричать'::text,'кричали'::text,'кричачи'::text,'Коли вони відкриють подарунки, діти закричать від радості.'::text),
(301839,33538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando abran los regalos, los niños ... de alegría.'::text,'gritarán'::text,'gritaron'::text,'gritando'::text,'Cuando abran los regalos, los niños gritarán de alegría.'::text),
(301838,33538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils ouvriront les cadeaux, les enfants ... de joie.'::text,'crieront'::text,'ont crié'::text,'criant'::text,'Quand ils ouvriront les cadeaux, les enfants crieront de joie.'::text),
(301841,33538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hediyeleri açınca çocuklar sevinçten ...'::text,'bağıracak'::text,'bağırdı'::text,'bağırarak'::text,'Hediyeleri açınca çocuklar sevinçten bağıracak.'::text),
(301842,33538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor kinyitják az ajándékokat, a gyerekek ... örömükben.'::text,'kiabálni fognak'::text,'kiabáltak'::text,'kiabálva'::text,'Amikor kinyitják az ajándékokat, a gyerekek kiabálni fognak örömükben.'::text),
(297885,33099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap: Der Wächter ... den Strand bis 18 Uhr überwachen.'::text,'wird'::text,'wird'::text,'überwacht'::text,'Roadmap: Der Wächter wird den Strand bis 18 Uhr überwachen.'::text),
(297889,33099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорожня карта: охоронець ... пляж до 18:00.'::text,'збирається охороняти'::text,'охоронятиме'::text,'охороняє'::text,'Дорожня карта: охоронець збирається охороняти пляж до 18:00.'::text),
(297888,33099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoja de ruta: el vigilante ... la playa hasta las 18:00.'::text,'va a vigilar'::text,'vigilará'::text,'vigila'::text,'Hoja de ruta: el vigilante va a vigilar la playa hasta las 18:00.'::text),
(297887,33099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feuille de route : le surveillant ... la plage jusqu''à 18 h.'::text,'va surveiller'::text,'surveillera'::text,'surveille'::text,'Feuille de route : le surveillant va surveiller la plage jusqu''à 18 h.'::text),
(297890,33099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol haritası: bekçi saat 18.00''e kadar plajı ...'::text,'gözetleyecek'::text,'gözetleyecek'::text,'gözetler'::text,'Yol haritası: bekçi saat 18.00''e kadar plajı gözetleyecek.'::text),
(297891,33099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ütemterv: az őr este 6-ig ... a strandot.'::text,'figyelni fogja'::text,'figyelni fogja'::text,'figyeli'::text,'Ütemterv: az őr este 6-ig figyelni fogja a strandot.'::text),
(297894,33100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wächter rennt zum Meer, also ... er nass werden. Meer ist Wasser.'::text,'wird'::text,'wird'::text,NULL::text,'Der Wächter rennt zum Meer, also wird er nass werden. Meer ist Wasser.'::text),
(297898,33100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Охоронець біжить до моря, тож він ... мокрим. Море — це вода.'::text,'збирається стати'::text,'стане'::text,NULL::text,'Охоронець біжить до моря, тож він збирається стати мокрим. Море — це вода.'::text),
(297897,33100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vigilante corre hacia el mar, así que ... empapado. El mar es agua.'::text,'va a acabar'::text,'acabará'::text,NULL::text,'El vigilante corre hacia el mar, así que va a acabar empapado. El mar es agua.'::text),
(297896,33100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le surveillant court vers la mer, donc il ... mouillé. La mer, c''est de l''eau.'::text,'va être'::text,'sera'::text,NULL::text,'Le surveillant court vers la mer, donc il va être mouillé. La mer, c''est de l''eau.'::text),
(297899,33100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekçi denize koşuyor, yani ... Deniz sudur.'::text,'ıslanacak.'::text,'ıslanacak.'::text,NULL::text,'Bekçi denize koşuyor, yani ıslanacak. Deniz sudur.'::text),
(297900,33100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az őr a tengerhez fut, ezért vizes ... A tenger víz.'::text,'lesz.'::text,'lesz.'::text,NULL::text,'Az őr a tengerhez fut, ezért vizes lesz. A tenger víz.'::text),
(297903,33101,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist ein cooler Wächter mit so viel ...'::text,'Selbstbewusstsein.'::text,'Selbstbewusstsein.'::text,'Lächeln.'::text,'Ehrlich, du bist ein cooler Wächter mit so viel Selbstbewusstsein.'::text),
(297907,33101,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти крутий охоронець із такою ...'::text,'впевненістю.'::text,'впевненістю.'::text,'усмішками.'::text,'Чесно, ти крутий охоронець із такою впевненістю.'::text),
(297906,33101,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, eres un vigilante guay con tanta ...'::text,'seguridad.'::text,'seguridad.'::text,'sonrisas.'::text,'En serio, eres un vigilante guay con tanta seguridad.'::text),
(297905,33101,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, t''es un surveillant cool avec tant de ...'::text,'confiance.'::text,'confiance.'::text,'sourires.'::text,'Franchement, t''es un surveillant cool avec tant de confiance.'::text),
(297908,33101,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o kadar ... dolu, havalı bir bekçisin.'::text,'özgüven'::text,'özgüvenler'::text,'gülümsemeler'::text,'Açıkçası o kadar özgüven dolu, havalı bir bekçisin.'::text),
(297909,33101,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, menő őr vagy ennyi ...'::text,'magabiztossággal.'::text,'magabiztossággal.'::text,'mosolyokkal.'::text,'Őszintén, menő őr vagy ennyi magabiztossággal.'::text),
(297912,33102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wächter sieht heute ... Schwimmer in Not.'::text,'keine'::text,'einige'::text,'viel'::text,'Der Wächter sieht heute keine Schwimmer in Not.'::text),
(297916,33102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Охоронець сьогодні не бачить ... плавців у біді.'::text,'жодних'::text,'якихось'::text,'багато'::text,'Охоронець сьогодні не бачить жодних плавців у біді.'::text),
(297915,33102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vigilante no ve hoy a ... bañista en apuros.'::text,'ningún'::text,'algunos'::text,'mucho'::text,'El vigilante no ve hoy a ningún bañista en apuros.'::text),
(297914,33102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le surveillant ne voit ... nageur en difficulté aujourd''hui.'::text,'aucun'::text,'des'::text,'beaucoup de'::text,'Le surveillant ne voit aucun nageur en difficulté aujourd''hui.'::text),
(297917,33102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekçi bugün başı dertte ... yüzücü görmüyor.'::text,'hiç'::text,'bazı'::text,'çok'::text,'Bekçi bugün başı dertte hiç yüzücü görmüyor.'::text),
(297918,33102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az őr ma nem lát ... bajba jutott úszót.'::text,'semmilyen'::text,'néhány'::text,'sok'::text,'Az őr ma nem lát semmilyen bajba jutott úszót.'::text),
(297921,33103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hinter dem Wächter am Strand ... eine gelbe Flagge.'::text,'ist'::text,'sind'::text,'sein'::text,'Hinter dem Wächter am Strand ist eine gelbe Flagge.'::text),
(297925,33103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На пляжі за охоронцем ... жовтий прапор.'::text,'є'::text,'є'::text,'бути'::text,'На пляжі за охоронцем є жовтий прапор.'::text),
(297924,33103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una bandera amarilla en la playa detrás del vigilante.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una bandera amarilla en la playa detrás del vigilante.'::text),
(297923,33103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un drapeau jaune sur la plage derrière le surveillant.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a un drapeau jaune sur la plage derrière le surveillant.'::text),
(297926,33103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plajda bekçinin arkasında sarı bir bayrak ...'::text,'var'::text,'var'::text,'olmak'::text,'Plajda bekçinin arkasında sarı bir bayrak var.'::text),
(297927,33103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A strandon az őr mögött egy sárga zászló ...'::text,'van'::text,'vannak'::text,'lenni'::text,'A strandon az őr mögött egy sárga zászló van.'::text),
(297939,33105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieser Wächter ... Profi werden, der surft echt so gut.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Bro, dieser Wächter sollte Profi werden, der surft echt so gut.'::text),
(297943,33105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей охоронець ... стати профі, він реально так круто серфить.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Бро, цей охоронець мав би стати профі, він реально так круто серфить.'::text),
(297942,33105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, este vigilante ... hacerse profesional, surfea de locos, en serio.'::text,'debería'::text,'debería'::text,'debería'::text,'Tío, este vigilante debería hacerse profesional, surfea de locos, en serio.'::text),
(297941,33105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce surveillant ... passer pro, il surfe trop bien, sérieux.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Frère, ce surveillant devrait passer pro, il surfe trop bien, sérieux.'::text),
(297944,33105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu bekçi profesyonel ..., cidden o kadar iyi sörf yapıyor.'::text,'olmalı'::text,'olmalı'::text,'olmalı'::text,'Kanka, bu bekçi profesyonel olmalı, cidden o kadar iyi sörf yapıyor.'::text),
(297945,33105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ennek az őrnek profinak ... lennie, komolyan, olyan jól szörfözik.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Tesó, ennek az őrnek profinak kellene lennie, komolyan, olyan jól szörfözik.'::text),
(297948,33106,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Wächter muss arbeiten, ... er surft ernsthaft eine Welle.'::text,'aber'::text,'also'::text,'weil'::text,'Bro, der Wächter muss arbeiten, aber er surft ernsthaft eine Welle.'::text),
(297952,33106,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, охоронець має працювати, ... він реально серфить на хвилі.'::text,'але'::text,'тому'::text,'бо'::text,'Бро, охоронець має працювати, але він реально серфить на хвилі.'::text),
(297951,33106,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el vigilante tiene que currar, ... está surfeando una ola, en serio.'::text,'pero'::text,'así que'::text,'porque'::text,'Tío, el vigilante tiene que currar, pero está surfeando una ola, en serio.'::text),
(297950,33106,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le surveillant doit bosser, ... il est en train de surfer une vague, sérieux.'::text,'mais'::text,'donc'::text,'parce que'::text,'Frère, le surveillant doit bosser, mais il est en train de surfer une vague, sérieux.'::text),
(297953,33106,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bekçinin çalışması lazım ... adam resmen dalga sörfü yapıyor.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kanka, bekçinin çalışması lazım ama adam resmen dalga sörfü yapıyor.'::text),
(297954,33106,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az őrnek dolgoznia kéne, ... komolyan egy hullámot szörfözik.'::text,'de'::text,'ezért'::text,'mert'::text,'Tesó, az őrnek dolgoznia kéne, de komolyan egy hullámot szörfözik.'::text),
(299316,33258,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der große Rucksack ... schwer.'::text,'ist'::text,'sind'::text,'bin'::text,'Der große Rucksack ist schwer.'::text),
(299320,33258,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Великий рюкзак ... важкий.'::text,'є'::text,'є'::text,'є'::text,'Великий рюкзак є важкий.'::text),
(299319,33258,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mochila grande ... pesada.'::text,'es'::text,'son'::text,'soy'::text,'La mochila grande es pesada.'::text),
(299318,33258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gros sac à dos ... lourd.'::text,'est'::text,'sont'::text,'suis'::text,'Le gros sac à dos est lourd.'::text),
(299321,33258,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük sırt çantası ağır ...'::text,''::text,NULL::text,NULL::text,'Büyük sırt çantası ağır.'::text),
(299322,33258,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy hátizsák ... nehéz.'::text,''::text,NULL::text,'vagyok'::text,'A nagy hátizsák nehéz.'::text),
(299325,33259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... einen schweren Rucksack den Grat hinauf.'::text,'trägt'::text,'tragen'::text,'trägt'::text,'Er trägt einen schweren Rucksack den Grat hinauf.'::text),
(299329,33259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... важкий рюкзак угору хребтом.'::text,'несе'::text,'нести'::text,'несе'::text,'Він несе важкий рюкзак угору хребтом.'::text),
(299328,33259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... una mochila pesada cresta arriba.'::text,'lleva'::text,'llevar'::text,'lleva'::text,'Él lleva una mochila pesada cresta arriba.'::text),
(299327,33259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... un sac à dos lourd en montant la crête.'::text,'porte'::text,'porter'::text,'porte'::text,'Il porte un sac à dos lourd en montant la crête.'::text),
(299330,33259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dağ sırtı boyunca yukarı ağır bir sırt çantası ...'::text,'taşır'::text,'taşımak'::text,'taşır'::text,'Dağ sırtı boyunca yukarı ağır bir sırt çantası taşır.'::text),
(299331,33259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nehéz hátizsákot ... fel a gerincen.'::text,'visz'::text,'vinni'::text,'visz'::text,'Egy nehéz hátizsákot visz fel a gerincen.'::text),
(299334,33260,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... mit einer sehr schweren Tasche auf dem Rücken gehen.'::text,'kann'::text,'kann'::text,'kann'::text,'Er kann mit einer sehr schweren Tasche auf dem Rücken gehen.'::text),
(299338,33260,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... ходити з дуже важкою сумкою на спині.'::text,'може'::text,'може'::text,'може'::text,'Він може ходити з дуже важкою сумкою на спині.'::text),
(299337,33260,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... caminar con una bolsa muy pesada a la espalda.'::text,'puede'::text,'puede'::text,'puede'::text,'Él puede caminar con una bolsa muy pesada a la espalda.'::text),
(299336,33260,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... marcher avec un sac très lourd sur le dos.'::text,'peut'::text,'peut'::text,'peut'::text,'Il peut marcher avec un sac très lourd sur le dos.'::text),
(299339,33260,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırtında çok ağır bir çantayla ...'::text,'yürüyebilir'::text,'yürüyebilir'::text,'yürüyebilir'::text,'Sırtında çok ağır bir çantayla yürüyebilir.'::text),
(299340,33260,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nagyon nehéz táskával a hátán is ... járni.'::text,'tud'::text,'tud'::text,'tud'::text,'Egy nagyon nehéz táskával a hátán is tud járni.'::text),
(299352,33262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein entspannter Tag, ganz klar. Gestern ... er einen schweren Turm aus Pfannen bergauf.'::text,'trug'::text,'trägt'::text,'trug'::text,'Ein entspannter Tag, ganz klar. Gestern trug er einen schweren Turm aus Pfannen bergauf.'::text),
(299356,33262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розслаблений день, аякже. Учора він ... важку вежу зі сковорідок угору.'::text,'ніс'::text,'несе'::text,'ніс'::text,'Розслаблений день, аякже. Учора він ніс важку вежу зі сковорідок угору.'::text),
(299355,33262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un día relajado, obviamente. Ayer ... una pesada torre de sartenes cuesta arriba.'::text,'llevó'::text,'lleva'::text,'llevó'::text,'Un día relajado, obviamente. Ayer llevó una pesada torre de sartenes cuesta arriba.'::text),
(299354,33262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une journée tranquille, évidemment. Hier, il ... une lourde tour de poêles en montée.'::text,'a porté'::text,'porte'::text,'a porté'::text,'Une journée tranquille, évidemment. Hier, il a porté une lourde tour de poêles en montée.'::text),
(299357,33262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahat bir gün, belli ki. Dün ağır bir tava kulesini yokuş yukarı ...'::text,'taşıdı'::text,'taşır'::text,'taşıdı'::text,'Rahat bir gün, belli ki. Dün ağır bir tava kulesini yokuş yukarı taşıdı.'::text),
(299358,33262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyugis nap, nyilván. Tegnap egy nehéz serpenyőtornyot ... fel a hegyre.'::text,'vitt'::text,'visz'::text,'vitt'::text,'Nyugis nap, nyilván. Tegnap egy nehéz serpenyőtornyot vitt fel a hegyre.'::text),
(299361,33263,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellos. Normalerweise packt er leicht, aber gestern ... er einen schweren Turm.'::text,'trug'::text,'trägt'::text,NULL::text,'Makellos. Normalerweise packt er leicht, aber gestern trug er einen schweren Turm.'::text),
(299365,33263,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганно. Зазвичай він пакується легко, але вчора ... важку вежу.'::text,'ніс'::text,'несе'::text,NULL::text,'Бездоганно. Зазвичай він пакується легко, але вчора ніс важку вежу.'::text),
(299364,33263,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impecable. Normalmente viaja ligero, pero ayer ... una torre pesada.'::text,'llevó'::text,'lleva'::text,NULL::text,'Impecable. Normalmente viaja ligero, pero ayer llevó una torre pesada.'::text),
(299363,33263,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Impeccable. D''habitude, il voyage léger, mais hier il ... une lourde tour.'::text,'a porté'::text,'porte'::text,NULL::text,'Impeccable. D''habitude, il voyage léger, mais hier il a porté une lourde tour.'::text),
(299366,33263,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz. Genelde hafif eşya toplar ama dün ağır bir kule ...'::text,'taşıdı'::text,'taşır'::text,NULL::text,'Kusursuz. Genelde hafif eşya toplar ama dün ağır bir kule taşıdı.'::text),
(299367,33263,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan. Általában könnyen pakol, de tegnap egy nehéz tornyot ...'::text,'vitt'::text,'visz'::text,NULL::text,'Hibátlan. Általában könnyen pakol, de tegnap egy nehéz tornyot vitt.'::text),
(299379,33265,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schwere Rucksack ist ein Albtraum! Er geht so ... den Grat hinauf!'::text,'langsam'::text,'Langsamkeit'::text,'langsamer'::text,'Der schwere Rucksack ist ein Albtraum! Er geht so langsam den Grat hinauf!'::text),
(299383,33265,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Важкий рюкзак — це жах! Він іде так ... угору хребтом!'::text,'повільно'::text,'повільність'::text,'повільніше'::text,'Важкий рюкзак — це жах! Він іде так повільно угору хребтом!'::text),
(299382,33265,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mochila pesada es una pesadilla! ¡Sube tan ... por la cresta!'::text,'lentamente'::text,'lentitud'::text,'más lento'::text,'¡La mochila pesada es una pesadilla! ¡Sube tan lentamente por la cresta!'::text),
(299381,33265,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sac lourd, c''est un cauchemar ! Il monte la crête si ... !'::text,'lentement'::text,'lenteur'::text,'plus lentement'::text,'Le sac lourd, c''est un cauchemar ! Il monte la crête si lentement !'::text),
(299384,33265,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağır çanta tam bir kâbus! Dağ sırtında o kadar ... yürüyor ki!'::text,'yavaşça'::text,'yavaşlık'::text,'daha yavaş'::text,'Ağır çanta tam bir kâbus! Dağ sırtında o kadar yavaşça yürüyor ki!'::text),
(299385,33265,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nehéz hátizsák egy rémálom! Olyan ... megy fel a gerincen!'::text,'lassan'::text,'lassúság'::text,'lassabban'::text,'A nehéz hátizsák egy rémálom! Olyan lassan megy fel a gerincen!'::text),
(295518,32836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unglaublich! Sie ... frische Brötchen aus dem Ofen!'::text,'holen'::text,'holen'::text,'holen'::text,'Unglaublich! Sie holen frische Brötchen aus dem Ofen!'::text),
(295522,32836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неймовірно! Вони ... свіжі булочки з духовки!'::text,'виймають'::text,'виймають'::text,'виймають'::text,'Неймовірно! Вони виймають свіжі булочки з духовки!'::text),
(295521,32836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Increíble! ¡... panecillos recién hechos del horno!'::text,'Están sacando'::text,'Sacan'::text,'Están sacando'::text,'¡Increíble! ¡Están sacando panecillos recién hechos del horno!'::text),
(295520,32836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Incroyable ! Elles ... des petits pains frais du four !'::text,'sont en train de sortir'::text,'sortent'::text,'sont en train de sortir'::text,'Incroyable ! Elles sont en train de sortir des petits pains frais du four !'::text),
(295523,32836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Fırından taze çörekler ...!'::text,'çıkarıyorlar'::text,'çıkarırlar'::text,'çıkarıyorlar'::text,'İnanılmaz! Fırından taze çörekler çıkarıyorlar!'::text),
(295524,32836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! Friss zsemléket ... ki a sütőből!'::text,'vesznek'::text,'vesznek'::text,'vesznek'::text,'Hihetetlen! Friss zsemléket vesznek ki a sütőből!'::text),
(295527,32837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise kaufen sie Brot, aber heute ... sie alles frisch! Unglaublich!'::text,'backen'::text,'backen'::text,NULL::text,'Normalerweise kaufen sie Brot, aber heute backen sie alles frisch! Unglaublich!'::text),
(295531,32837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вони купують хліб, але сьогодні ... все свіже! Неймовірно!'::text,'печуть'::text,'печуть'::text,NULL::text,'Зазвичай вони купують хліб, але сьогодні печуть все свіже! Неймовірно!'::text),
(295530,32837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente compran pan, ¡pero hoy lo ... todo recién hecho! ¡Increíble!'::text,'están horneando'::text,'hornean'::text,NULL::text,'Normalmente compran pan, ¡pero hoy lo están horneando todo recién hecho! ¡Increíble!'::text),
(295529,32837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elles achètent du pain, mais aujourd''hui elles ... tout frais ! Incroyable !'::text,'sont en train de préparer'::text,'préparent'::text,NULL::text,'D''habitude, elles achètent du pain, mais aujourd''hui elles sont en train de préparer tout frais ! Incroyable !'::text),
(295532,32837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde ekmek alırlar ama bugün her şeyi taze taze ...! İnanılmaz!'::text,'pişiriyorlar'::text,'pişirirler'::text,NULL::text,'Genelde ekmek alırlar ama bugün her şeyi taze taze pişiriyorlar! İnanılmaz!'::text),
(295533,32837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában kenyeret vesznek, de ma mindent frissen ...! Hihetetlen!'::text,'sütnek'::text,'sütnek'::text,NULL::text,'Általában kenyeret vesznek, de ma mindent frissen sütnek! Hihetetlen!'::text),
(295536,32838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen ... die Frauen wieder frisches Brot backen.'::text,'werden'::text,'backten'::text,'backend'::text,'Morgen werden die Frauen wieder frisches Brot backen.'::text),
(295540,32838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра жінки знову ... свіжий хліб.'::text,'спечуть'::text,'спекли'::text,'печучи'::text,'Завтра жінки знову спечуть свіжий хліб.'::text),
(295539,32838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana las mujeres ... pan recién hecho otra vez.'::text,'hornearán'::text,'hornearon'::text,'horneando'::text,'Mañana las mujeres hornearán pan recién hecho otra vez.'::text),
(295538,32838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain, les femmes ... encore du pain frais.'::text,'feront'::text,'ont fait'::text,'faisant'::text,'Demain, les femmes feront encore du pain frais.'::text),
(295541,32838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın kadınlar yine taze ekmek ...'::text,'pişirecek'::text,'pişirdi'::text,'pişirerek'::text,'Yarın kadınlar yine taze ekmek pişirecek.'::text),
(295542,32838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap a nők újra friss kenyeret ...'::text,'fognak sütni'::text,'sütöttek'::text,'sütve'::text,'Holnap a nők újra friss kenyeret fognak sütni.'::text),
(295554,32840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, das Blech ist aus dem Ofen, sie ... ein frisches Brötchen essen, echt.'::text,'wird'::text,'wird'::text,NULL::text,'Yo, das Blech ist aus dem Ofen, sie wird ein frisches Brötchen essen, echt.'::text),
(295558,32840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йоу, деко вже з духовки, вона ... свіжу булочку, реально.'::text,'збирається з''їсти'::text,'з''їсть'::text,NULL::text,'Йоу, деко вже з духовки, вона збирається з''їсти свіжу булочку, реально.'::text),
(295557,32840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la bandeja ya está fuera del horno, ella ... un panecillo recién hecho, en serio.'::text,'va a comerse'::text,'se comerá'::text,NULL::text,'Tío, la bandeja ya está fuera del horno, ella va a comerse un panecillo recién hecho, en serio.'::text),
(295556,32840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, la plaque est sortie du four, elle ... un petit pain frais, sérieux.'::text,'va manger'::text,'mangera'::text,NULL::text,'Wesh, la plaque est sortie du four, elle va manger un petit pain frais, sérieux.'::text),
(295559,32840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tepsi fırından çıktı, taze bir çörek ..., cidden.'::text,'yiyecek'::text,'yiyecek'::text,NULL::text,'Kanka, tepsi fırından çıktı, taze bir çörek yiyecek, cidden.'::text),
(295560,32840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, kint a tepsi a sütőből, meg ... enni egy friss zsemlét, komolyan.'::text,'fog'::text,'fog'::text,NULL::text,'Tesó, kint a tepsi a sütőből, meg fog enni egy friss zsemlét, komolyan.'::text),
(295563,32841,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Frisches Brot ist 3 Euro ... als altes Brot.'::text,'teurer'::text,'teurer'::text,'am teuersten'::text,'Bericht: Frisches Brot ist 3 Euro teurer als altes Brot.'::text),
(295567,32841,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: свіжий хліб на 3 євро ... за старий хліб.'::text,'більш дорогий'::text,'дорожчий'::text,'найдорожчий'::text,'Звіт: свіжий хліб на 3 євро більш дорогий за старий хліб.'::text),
(295566,32841,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: el pan recién hecho es 3 euros ... que el pan duro.'::text,'más caro'::text,'más caro'::text,'el más caro'::text,'Informe: el pan recién hecho es 3 euros más caro que el pan duro.'::text),
(295565,32841,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : le pain frais est ... de 3 euros que le pain rassis.'::text,'plus cher'::text,'plus cher'::text,'le plus cher'::text,'Rapport : le pain frais est plus cher de 3 euros que le pain rassis.'::text),
(295568,32841,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: taze ekmek bayat ekmekten 3 euro ...'::text,'daha pahalı'::text,'daha pahalı'::text,'en pahalı'::text,'Rapor: taze ekmek bayat ekmekten 3 euro daha pahalı.'::text),
(295569,32841,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: a friss kenyér 3 euróval ... a réginél.'::text,'drágább'::text,'drágább'::text,'legdrágább'::text,'Jelentés: a friss kenyér 3 euróval drágább a réginél.'::text),
(295572,32842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Brot ist frisch, also hält sie es ..., weil es frisch ist.'::text,'fröhlich'::text,'fröhlich'::text,'Fröhlichkeit'::text,'Das Brot ist frisch, also hält sie es fröhlich, weil es frisch ist.'::text),
(295576,32842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хліб свіжий, тож вона тримає його ..., бо він свіжий.'::text,'радісно'::text,'радісний'::text,'радість'::text,'Хліб свіжий, тож вона тримає його радісно, бо він свіжий.'::text),
(295575,32842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pan está recién hecho, así que ella lo sostiene ... porque está recién hecho.'::text,'felizmente'::text,'feliz'::text,'felicidad'::text,'El pan está recién hecho, así que ella lo sostiene felizmente porque está recién hecho.'::text),
(295574,32842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pain est frais, alors elle le tient ... parce qu''il est frais.'::text,'joyeusement'::text,'joyeux'::text,'joie'::text,'Le pain est frais, alors elle le tient joyeusement parce qu''il est frais.'::text),
(295577,32842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekmek taze, bu yüzden onu ... tutuyor çünkü taze.'::text,'mutlu bir şekilde'::text,'mutlu'::text,'mutluluk'::text,'Ekmek taze, bu yüzden onu mutlu bir şekilde tutuyor çünkü taze.'::text),
(295578,32842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kenyér friss, ezért ... tartja, mert friss.'::text,'boldogan'::text,'boldog'::text,'boldogság'::text,'A kenyér friss, ezért boldogan tartja, mert friss.'::text),
(321951,35773,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Krankenschwester hat eine Rolle Band, und ... Band ist weiß.'::text,'das'::text,'ein'::text,'ein'::text,'Die Krankenschwester hat eine Rolle Band, und das Band ist weiß.'::text),
(321955,35773,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медсестра має рулон стрічки, і ... стрічка біла.'::text,''::text,NULL::text,NULL::text,'Медсестра має рулон стрічки, і стрічка біла.'::text),
(321954,35773,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La enfermera tiene un rollo de cinta, y ... cinta es blanca.'::text,'la'::text,'una'::text,'una'::text,'La enfermera tiene un rollo de cinta, y la cinta es blanca.'::text),
(321953,35773,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''infirmière a un rouleau de bande, et ... bande est blanche.'::text,'la'::text,'une'::text,'une'::text,'L''infirmière a un rouleau de bande, et la bande est blanche.'::text),
(321956,35773,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşirenin bir rulo bandı var ve ... bant beyaz.'::text,''::text,'bir'::text,'bir'::text,'Hemşirenin bir rulo bandı var ve bant beyaz.'::text),
(321957,35773,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ápolónak van egy tekercs szalagja, és ... szalag fehér.'::text,'a'::text,'egy'::text,'egy'::text,'Az ápolónak van egy tekercs szalagja, és a szalag fehér.'::text),
(321960,35774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! ... Rollen Band bedecken seinen ganzen Körper!'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Katastrophe! Diese Rollen Band bedecken seinen ganzen Körper!'::text),
(321964,35774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! ... рулони стрічки вкривають усе його тіло!'::text,'Ці'::text,'Цей'::text,'Той'::text,'Катастрофа! Ці рулони стрічки вкривають усе його тіло!'::text),
(321963,35774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡... rollos de cinta le cubren todo el cuerpo!'::text,'Estos'::text,'Este'::text,'Ese'::text,'¡Desastre! ¡Estos rollos de cinta le cubren todo el cuerpo!'::text),
(321962,35774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! ... rouleaux de bande couvrent tout son corps !'::text,'Ces'::text,'Ce'::text,'Ce'::text,'Catastrophe ! Ces rouleaux de bande couvrent tout son corps !'::text),
(321965,35774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! ... bant ruloları bütün vücudunu kaplıyor!'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Felaket! Bu bant ruloları bütün vücudunu kaplıyor!'::text),
(321966,35774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! ... a szalagtekercsek az egész testét beborítják!'::text,'Ezek'::text,'Ez'::text,'Az'::text,'Katasztrófa! Ezek a szalagtekercsek az egész testét beborítják!'::text),
(321969,35775,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Das Band bedeckt ... ganzen Körper und Kopf!'::text,'seinen'::text,'ihren'::text,'ihren'::text,'Albtraum! Das Band bedeckt seinen ganzen Körper und Kopf!'::text),
(321973,35775,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Стрічка вкриває все ... тіло й голову!'::text,'його'::text,'її'::text,'їхнє'::text,'Жах! Стрічка вкриває все його тіло й голову!'::text),
(321972,35775,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡La cinta le cubre todo ... cuerpo y la cabeza!'::text,'su'::text,'su'::text,'su'::text,'¡Pesadilla! ¡La cinta le cubre todo su cuerpo y la cabeza!'::text),
(321971,35775,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! La bande couvre tout ... corps et sa tête !'::text,'son'::text,'son'::text,'leur'::text,'Cauchemar ! La bande couvre tout son corps et sa tête !'::text),
(321974,35775,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bant ... bütün vücudunu ve başını kaplıyor!'::text,'onun'::text,'onun'::text,'onların'::text,'Kâbus! Bant onun bütün vücudunu ve başını kaplıyor!'::text),
(321975,35775,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A szalag beborítja az egész ... és a fejét!'::text,'testét'::text,'testét'::text,'testüket'::text,'Rémálom! A szalag beborítja az egész testét és a fejét!'::text),
(321987,35777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Kollegen wickeln immer weiter das Band ab.'::text,'Zwei'::text,'Zweite'::text,'Zweimal'::text,'Zwei Kollegen wickeln immer weiter das Band ab.'::text),
(321991,35777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... колег усе розмотують стрічку.'::text,'Двоє'::text,'Другий'::text,'Двічі'::text,'Двоє колег усе розмотують стрічку.'::text),
(321990,35777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... compañeros siguen desenrollando la cinta.'::text,'Dos'::text,'Segundo'::text,'Dos veces'::text,'Dos compañeros siguen desenrollando la cinta.'::text),
(321989,35777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... collègues continuent de dérouler la bande.'::text,'Deux'::text,'Deuxième'::text,'Deux fois'::text,'Deux collègues continuent de dérouler la bande.'::text),
(321992,35777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... iş arkadaşı bandı açmaya devam ediyor.'::text,'İki'::text,'İkinci'::text,'İki kez'::text,'İki iş arkadaşı bandı açmaya devam ediyor.'::text),
(321993,35777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kolléga folyamatosan tekeri le a szalagot.'::text,'Két'::text,'Második'::text,'Kétszer'::text,'Két kolléga folyamatosan tekeri le a szalagot.'::text),
(321996,35778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend haben sie so viel ... für den armen Kerl verbraucht.'::text,'Band'::text,'Band'::text,'ein Band'::text,'Mädel, anscheinend haben sie so viel Band für den armen Kerl verbraucht.'::text),
(322000,35778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, вони витратили стільки ... на того бідолаху.'::text,'стрічки'::text,'стрічки'::text,'стрічки'::text,'Подружко, кажуть, вони витратили стільки стрічки на того бідолаху.'::text),
(321999,35778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer gastaron tanta ... en ese pobre chico.'::text,'cinta'::text,'cinta'::text,'una cinta'::text,'Tía, al parecer gastaron tanta cinta en ese pobre chico.'::text),
(321998,35778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment ils ont utilisé tellement de ... pour ce pauvre gars.'::text,'bande'::text,'bande'::text,'une bande'::text,'Ma belle, apparemment ils ont utilisé tellement de bande pour ce pauvre gars.'::text),
(322001,35778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan o zavallı adama o kadar çok ... harcamışlar.'::text,'bant'::text,'bantlar'::text,'bir bant'::text,'Kızım, anlaşılan o zavallı adama o kadar çok bant harcamışlar.'::text),
(322002,35778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag annyi ... használtak el arra a szegény srácra.'::text,'szalagot'::text,'szalagot'::text,'egy szalagot'::text,'Csajszi, állítólag annyi szalagot használtak el arra a szegény srácra.'::text),
(322005,35779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bleibst ruhig mit so ... Band um dich herum. Respekt.'::text,'viel'::text,'viele'::text,'ein paar'::text,'Ehrlich, du bleibst ruhig mit so viel Band um dich herum. Respekt.'::text),
(322009,35779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти лишаєшся спокійним, коли навколо тебе так ... стрічки. Респект.'::text,'багато'::text,'багато'::text,'кілька'::text,'Чесно, ти лишаєшся спокійним, коли навколо тебе так багато стрічки. Респект.'::text),
(322008,35779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, mantienes la calma con ... cinta a tu alrededor. Chapó.'::text,'tanta'::text,'tantos'::text,'unas pocas'::text,'En serio, mantienes la calma con tanta cinta a tu alrededor. Chapó.'::text),
(322007,35779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu restes calme avec ... bande autour de toi. Respect.'::text,'autant de'::text,'autant de'::text,'quelques'::text,'Franchement, tu restes calme avec autant de bande autour de toi. Respect.'::text),
(322010,35779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası etrafında bu kadar ... bant varken sakin kalıyorsun. Saygılar.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Açıkçası etrafında bu kadar çok bant varken sakin kalıyorsun. Saygılar.'::text),
(322011,35779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, nyugodt maradsz, pedig ilyen ... szalag van körülötted. Le a kalappal.'::text,'sok'::text,'sok'::text,'pár'::text,'Őszintén, nyugodt maradsz, pedig ilyen sok szalag van körülötted. Le a kalappal.'::text),
(296580,32954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach der Arbeit ... sich die Freunde auf dem Dach.'::text,'treffen'::text,'trifft'::text,'treffend'::text,'Nach der Arbeit treffen sich die Freunde auf dem Dach.'::text),
(296584,32954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після роботи друзі ... на даху.'::text,'збираються'::text,'збирається'::text,'збираючись'::text,'Після роботи друзі збираються на даху.'::text),
(296583,32954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después del trabajo, los amigos se ... en la azotea.'::text,'reúnen'::text,'reúne'::text,'reuniendo'::text,'Después del trabajo, los amigos se reúnen en la azotea.'::text),
(296582,32954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après le travail, les amis se ... sur le toit.'::text,'réunissent'::text,'réunit'::text,'réunissant'::text,'Après le travail, les amis se réunissent sur le toit.'::text),
(296585,32954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş çıkışı arkadaşlar çatıda ...'::text,'toplanır'::text,'toplanır'::text,'toplanarak'::text,'İş çıkışı arkadaşlar çatıda toplanır.'::text),
(296586,32954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Munka után a barátok a tetőn ...'::text,'gyűlnek össze'::text,'gyűlik össze'::text,'összegyűlve'::text,'Munka után a barátok a tetőn gyűlnek össze.'::text),
(296589,32955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zehn Freunde ... sich an dieser langen Theke treffen.'::text,'können'::text,'können'::text,'können'::text,'Zehn Freunde können sich an dieser langen Theke treffen.'::text),
(296593,32955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Десять друзів ... зібратися біля цієї довгої стійки.'::text,'можуть'::text,'можуть'::text,'можуть'::text,'Десять друзів можуть зібратися біля цієї довгої стійки.'::text),
(296592,32955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diez amigos ... reunirse en esta barra larga.'::text,'pueden'::text,'pueden'::text,'pueden'::text,'Diez amigos pueden reunirse en esta barra larga.'::text),
(296591,32955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dix amis ... se réunir à ce long comptoir.'::text,'peuvent'::text,'peuvent'::text,'peuvent'::text,'Dix amis peuvent se réunir à ce long comptoir.'::text),
(296594,32955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On arkadaş bu uzun tezgâhta ...'::text,'toplanabilir'::text,'toplanabilir'::text,'toplanabilir'::text,'On arkadaş bu uzun tezgâhta toplanabilir.'::text),
(296595,32955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz barát ... összegyűlni ennél a hosszú pultnál.'::text,'tud'::text,'tud'::text,'tud'::text,'Tíz barát tud összegyűlni ennél a hosszú pultnál.'::text),
(296607,32957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... sich die Freunde auf dem Dach auf einen Drink.'::text,'trafen'::text,'treffen'::text,'treffend'::text,'Gestern Abend trafen sich die Freunde auf dem Dach auf einen Drink.'::text),
(296611,32957,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері друзі ... на даху, щоб випити.'::text,'зібралися'::text,'збираються'::text,'збираючись'::text,'Учора ввечері друзі зібралися на даху, щоб випити.'::text),
(296610,32957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche los amigos se ... en la azotea para tomar algo.'::text,'reunieron'::text,'reúnen'::text,'reuniendo'::text,'Anoche los amigos se reunieron en la azotea para tomar algo.'::text),
(296609,32957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, les amis se ... sur le toit pour boire un verre.'::text,'sont réunis'::text,'réunissent'::text,'réunissant'::text,'Hier soir, les amis se sont réunis sur le toit pour boire un verre.'::text),
(296612,32957,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşam arkadaşlar bir şeyler içmek için çatıda ...'::text,'toplandı'::text,'toplanır'::text,'toplanarak'::text,'Dün akşam arkadaşlar bir şeyler içmek için çatıda toplandı.'::text),
(296613,32957,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este a barátok ... a tetőn egy italra.'::text,'összegyűltek'::text,'összegyűlnek'::text,'összegyűlve'::text,'Tegnap este a barátok összegyűltek a tetőn egy italra.'::text),
(296616,32958,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise treffen sie sich unten, aber gestern ... sie sich auf dem Dach.'::text,'trafen'::text,'treffen'::text,NULL::text,'Normalerweise treffen sie sich unten, aber gestern trafen sie sich auf dem Dach.'::text),
(296620,32958,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вони збираються внизу, але вчора ... на даху.'::text,'зібралися'::text,'збираються'::text,NULL::text,'Зазвичай вони збираються внизу, але вчора зібралися на даху.'::text),
(296619,32958,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente se reúnen abajo, pero ayer se ... en la azotea.'::text,'reunieron'::text,'reúnen'::text,NULL::text,'Normalmente se reúnen abajo, pero ayer se reunieron en la azotea.'::text),
(296618,32958,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, ils se réunissent en bas, mais hier ils se ... sur le toit.'::text,'sont réunis'::text,'réunissent'::text,NULL::text,'D''habitude, ils se réunissent en bas, mais hier ils se sont réunis sur le toit.'::text),
(296621,32958,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde aşağıda toplanırlar ama dün çatıda ...'::text,'toplandılar'::text,'toplanırlar'::text,NULL::text,'Genelde aşağıda toplanırlar ama dün çatıda toplandılar.'::text),
(296622,32958,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában lent gyűlnek össze, de tegnap a tetőn ...'::text,'gyűltek össze'::text,'gyűlnek össze'::text,NULL::text,'Általában lent gyűlnek össze, de tegnap a tetőn gyűltek össze.'::text),
(296634,32960,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, du ... deine Freunde öfter hier versammeln.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Mal ehrlich, du solltest deine Freunde öfter hier versammeln.'::text),
(296638,32960,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... частіше збирати тут своїх друзів.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Не буду брехати, ти мав би частіше збирати тут своїх друзів.'::text),
(296637,32960,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... reunir a tus amigos aquí más a menudo.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'No voy a mentir, deberías reunir a tus amigos aquí más a menudo.'::text),
(296636,32960,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... réunir tes amis ici plus souvent.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Je vais pas mentir, tu devrais réunir tes amis ici plus souvent.'::text),
(296639,32960,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, arkadaşlarını buraya daha sık ...'::text,'toplamalısın'::text,'toplamalısın'::text,'toplamalısın'::text,'Yalan yok, arkadaşlarını buraya daha sık toplamalısın.'::text),
(296640,32960,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, gyakrabban ... ide összehívnod a barátaidat.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Nem fogok hazudni, gyakrabban kellene ide összehívnod a barátaidat.'::text),
(296643,32961,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du suchst tolle Orte aus, ... treffen sich deine Freunde hier. Respekt.'::text,'also'::text,'aber'::text,'oder'::text,'Du suchst tolle Orte aus, also treffen sich deine Freunde hier. Respekt.'::text),
(296647,32961,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти обираєш класні місця, ... твої друзі збираються тут. Респект.'::text,'тому'::text,'але'::text,'або'::text,'Ти обираєш класні місця, тому твої друзі збираються тут. Респект.'::text),
(296646,32961,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eliges sitios geniales, ... tus amigos se reúnen aquí. Chapó.'::text,'así que'::text,'pero'::text,'o'::text,'Eliges sitios geniales, así que tus amigos se reúnen aquí. Chapó.'::text),
(296645,32961,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu choisis des super spots, ... tes amis se réunissent ici. Respect.'::text,'donc'::text,'mais'::text,'ou'::text,'Tu choisis des super spots, donc tes amis se réunissent ici. Respect.'::text),
(296648,32961,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika yerler seçiyorsun ... arkadaşların burada toplanıyor. Saygılar.'::text,'bu yüzden'::text,'ama'::text,'veya'::text,'Harika yerler seçiyorsun bu yüzden arkadaşların burada toplanıyor. Saygılar.'::text),
(296649,32961,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szuper helyeket választasz, ... itt gyűlnek össze a barátaid. Le a kalappal.'::text,'ezért'::text,'de'::text,'vagy'::text,'Szuper helyeket választasz, ezért itt gyűlnek össze a barátaid. Le a kalappal.'::text),
(306597,34067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Frauen ... ein Lärmproblem.'::text,'haben'::text,'hat'::text,'haben'::text,'Die beiden Frauen haben ein Lärmproblem.'::text),
(306601,34067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці дві жінки ... проблему з шумом.'::text,'мають'::text,'має'::text,'мають'::text,'Ці дві жінки мають проблему з шумом.'::text),
(306600,34067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos mujeres ... un problema de ruido.'::text,'tienen'::text,'tiene'::text,'tienen'::text,'Las dos mujeres tienen un problema de ruido.'::text),
(306599,34067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux femmes ... un problème de bruit.'::text,'ont'::text,'a'::text,'ont'::text,'Les deux femmes ont un problème de bruit.'::text),
(306602,34067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki kadının bir gürültü sorunu ...'::text,'var'::text,'var'::text,'var'::text,'İki kadının bir gürültü sorunu var.'::text),
(306603,34067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két nőnek zajproblémája ...'::text,'van'::text,'van'::text,'van'::text,'A két nőnek zajproblémája van.'::text),
(306606,34068,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hunde machen zwei laute ...'::text,'Geräusche.'::text,'Geräusch.'::text,'Geräusche.'::text,'Die Hunde machen zwei laute Geräusche.'::text),
(306610,34068,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собаки видають два гучні ...'::text,'звуки.'::text,'звук.'::text,'звуки.'::text,'Собаки видають два гучні звуки.'::text),
(306609,34068,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los perros hacen dos ... fuertes.'::text,'ruidos'::text,'ruido'::text,'ruidos'::text,'Los perros hacen dos ruidos fuertes.'::text),
(306608,34068,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chiens font deux ... forts.'::text,'bruits'::text,'bruit'::text,'bruits'::text,'Les chiens font deux bruits forts.'::text),
(306611,34068,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekler iki yüksek ... çıkarıyor.'::text,'ses'::text,'ses'::text,'sesler'::text,'Köpekler iki yüksek ses çıkarıyor.'::text),
(306612,34068,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyák két hangos ... adnak ki.'::text,'hangot'::text,'hangot'::text,'hangot'::text,'A kutyák két hangos hangot adnak ki.'::text),
(306615,34069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund macht ein Geräusch. ... Geräusch tut ihnen in den Ohren weh.'::text,'Das'::text,'Ein'::text,'Ein'::text,'Der Hund macht ein Geräusch. Das Geräusch tut ihnen in den Ohren weh.'::text),
(306619,34069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собака видає звук. ... звук ріже їм вуха.'::text,''::text,NULL::text,NULL::text,'Собака видає звук. Звук ріже їм вуха.'::text),
(306618,34069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro hace un ruido. ... ruido les hace daño en los oídos.'::text,'El'::text,'Un'::text,'Un'::text,'El perro hace un ruido. El ruido les hace daño en los oídos.'::text),
(306617,34069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien fait un bruit. ... bruit leur fait mal aux oreilles.'::text,'Le'::text,'Un'::text,'Un'::text,'Le chien fait un bruit. Le bruit leur fait mal aux oreilles.'::text),
