(294359,32707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le robinet coule. Elle ... la baignoire de mousse.'::text,'va remplir'::text,'remplira'::text,NULL::text,'Le robinet coule. Elle va remplir la baignoire de mousse.'::text),
(294362,32707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Musluk açık. Küveti köpükle ...'::text,'dolduracak'::text,'dolduracak'::text,NULL::text,'Musluk açık. Küveti köpükle dolduracak.'::text),
(294363,32707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Folyik a csap. Habbal ... a kádat.'::text,'fogja megtölteni'::text,'fogja megtölteni'::text,NULL::text,'Folyik a csap. Habbal fogja megtölteni a kádat.'::text),
(294366,32708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagt sich: Ich ... diese Wanne heute bis oben füllen.'::text,'muss'::text,'muss'::text,'darf nicht'::text,'Sie sagt sich: Ich muss diese Wanne heute bis oben füllen.'::text),
(294370,32708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона каже собі: я ... сьогодні наповнити цю ванну до країв.'::text,'мушу'::text,'маю'::text,'не повинна'::text,'Вона каже собі: я мушу сьогодні наповнити цю ванну до країв.'::text),
(294369,32708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice a sí misma: hoy ... llenar esta bañera hasta arriba.'::text,'debo'::text,'tengo que'::text,'no debo'::text,'Se dice a sí misma: hoy debo llenar esta bañera hasta arriba.'::text),
(294368,32708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se dit : je ... remplir cette baignoire à ras bord aujourd''hui.'::text,'dois'::text,'dois'::text,'ne dois pas'::text,'Elle se dit : je dois remplir cette baignoire à ras bord aujourd''hui.'::text),
(294371,32708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendine şöyle diyor: bugün bu küveti ağzına kadar ...'::text,'doldurmalıyım'::text,'doldurmak zorundayım'::text,'doldurmamalıyım'::text,'Kendine şöyle diyor: bugün bu küveti ağzına kadar doldurmalıyım.'::text),
(294372,32708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondja magának: ma színültig meg ... töltenem ezt a kádat.'::text,'kell'::text,'kell'::text,'nem szabad'::text,'Azt mondja magának: ma színültig meg kell töltenem ezt a kádat.'::text),
(294375,32709,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wochenziel: 1 Bad. Sie ... heute die Wanne füllen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Wochenziel: 1 Bad. Sie sollte heute die Wanne füllen.'::text),
(294379,32709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тижнева ціль: 1 ванна. Вона ... сьогодні наповнити ванну.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Тижнева ціль: 1 ванна. Вона мала б сьогодні наповнити ванну.'::text),
(294378,32709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo semanal: 1 baño. Ella ... llenar la bañera hoy.'::text,'debería'::text,'debería'::text,'debería'::text,'Objetivo semanal: 1 baño. Ella debería llenar la bañera hoy.'::text),
(294377,32709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif de la semaine : 1 bain. Elle ... remplir la baignoire aujourd''hui.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Objectif de la semaine : 1 bain. Elle devrait remplir la baignoire aujourd''hui.'::text),
(294380,32709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haftalık hedef: 1 banyo. Bugün küveti ...'::text,'doldurmalı'::text,'doldurmalı'::text,'doldurmalı'::text,'Haftalık hedef: 1 banyo. Bugün küveti doldurmalı.'::text),
(294381,32709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heti cél: 1 fürdés. Ma meg ... töltenie a kádat.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Heti cél: 1 fürdés. Ma meg kellene töltenie a kádat.'::text),
(294384,32710,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine leere Wanne ist nicht voll, ... füllt sie sie.'::text,'also'::text,'weil'::text,'aber'::text,'Eine leere Wanne ist nicht voll, also füllt sie sie.'::text),
(294388,32710,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Порожня ванна не повна, ... вона її наповнює.'::text,'тому'::text,'бо'::text,'але'::text,'Порожня ванна не повна, тому вона її наповнює.'::text),
(294387,32710,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una bañera vacía no está llena, ... ella la llena.'::text,'así que'::text,'porque'::text,'pero'::text,'Una bañera vacía no está llena, así que ella la llena.'::text),
(294386,32710,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une baignoire vide n''est pas pleine, ... elle la remplit.'::text,'donc'::text,'parce que'::text,'mais'::text,'Une baignoire vide n''est pas pleine, donc elle la remplit.'::text),
(294389,32710,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boş küvet dolu değildir ... onu dolduruyor.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Boş küvet dolu değildir bu yüzden onu dolduruyor.'::text),
(294390,32710,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy üres kád nincs tele, ... megtölti.'::text,'ezért'::text,'mert'::text,'de'::text,'Egy üres kád nincs tele, ezért megtölti.'::text),
(322689,35855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Barbier ... für diesen dichten Bart viel Zeit brauchen.'::text,'wird'::text,'ist'::text,'war'::text,'Der Barbier wird für diesen dichten Bart viel Zeit brauchen.'::text),
(322693,35855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Барбер ... потребувати багато часу на цю густу бороду.'::text,'буде'::text,'є'::text,'був'::text,'Барбер буде потребувати багато часу на цю густу бороду.'::text),
(322692,35855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barbero ... necesitar mucho tiempo para esta barba tan espesa.'::text,''::text,'está'::text,'estaba'::text,'El barbero necesitar mucho tiempo para esta barba tan espesa.'::text),
(322691,35855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le barbier ... avoir besoin de beaucoup de temps pour cette barbe épaisse.'::text,''::text,'est'::text,'était'::text,'Le barbier avoir besoin de beaucoup de temps pour cette barbe épaisse.'::text),
(322694,35855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Berberin bu gür sakal için çok zamana ...'::text,'ihtiyacı olacak'::text,NULL::text,'idi'::text,'Berberin bu gür sakal için çok zamana ihtiyacı olacak.'::text),
(322695,35855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A borbélynak sok időre ... szüksége erre a dús szakállra.'::text,'lesz'::text,'van'::text,'volt'::text,'A borbélynak sok időre lesz szüksége erre a dús szakállra.'::text),
(322698,35856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Er ... seinen dichten Bart abschneiden!'::text,'wird'::text,'wird'::text,'wird'::text,'Katastrophe! Er wird seinen dichten Bart abschneiden!'::text),
(322702,35856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Він ... зістригти свою густу бороду!'::text,'збирається'::text,'збирається'::text,'збирається'::text,'Катастрофа! Він збирається зістригти свою густу бороду!'::text),
(322701,35856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Él ... cortarse la barba espesa!'::text,'va a'::text,'va a'::text,'va a'::text,'¡Desastre! ¡Él va a cortarse la barba espesa!'::text),
(322700,35856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il ... couper sa barbe épaisse !'::text,'va'::text,'va'::text,'va'::text,'Catastrophe ! Il va couper sa barbe épaisse !'::text),
(322703,35856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Gür sakalını ...!'::text,'kesecek'::text,'kesecek'::text,'kesecek'::text,'Felaket! Gür sakalını kesecek!'::text),
(322704,35856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Le ... vágni a dús szakállát!'::text,'fogja'::text,'fogja'::text,'fogja'::text,'Katasztrófa! Le fogja vágni a dús szakállát!'::text),
(322707,35857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut unglaublich! Der Bart ist so dicht, er ... bis zum Boden reichen!'::text,'wird'::text,'wird'::text,NULL::text,'Absolut unglaublich! Der Bart ist so dicht, er wird bis zum Boden reichen!'::text),
(322711,35857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто неймовірно! Ця борода така густа, що вона ... дістати до підлоги!'::text,'збирається'::text,'буде'::text,NULL::text,'Просто неймовірно! Ця борода така густа, що вона збирається дістати до підлоги!'::text),
(322710,35857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente increíble! ¡Esa barba es tan espesa que ... llegar al suelo!'::text,'va a'::text,NULL::text,NULL::text,'¡Absolutamente increíble! ¡Esa barba es tan espesa que va a llegar al suelo!'::text),
(322709,35857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument incroyable ! Cette barbe est si épaisse qu''elle ... toucher le sol !'::text,'va'::text,NULL::text,NULL::text,'Absolument incroyable ! Cette barbe est si épaisse qu''elle va toucher le sol !'::text),
(322712,35857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! O sakal o kadar gür ki yere kadar ...!'::text,'uzanacak'::text,'uzanacak'::text,NULL::text,'İnanılmaz! O sakal o kadar gür ki yere kadar uzanacak!'::text),
(322713,35857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen hihetetlen! Az a szakáll olyan dús, hogy a földig ... érni!'::text,'fog'::text,'fog'::text,NULL::text,'Teljesen hihetetlen! Az a szakáll olyan dús, hogy a földig fog érni!'::text),
(322716,35858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, der Barbier hat gesagt, der Bart des alten Mannes ist ... als der da.'::text,'dichter'::text,'dichter'::text,'am dichtesten'::text,'Mädel, der Barbier hat gesagt, der Bart des alten Mannes ist dichter als der da.'::text),
(322720,35858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, барбер сказав, що борода того старого ... за ту.'::text,'густіша'::text,'більш густа'::text,'найгустіша'::text,'Подружко, барбер сказав, що борода того старого густіша за ту.'::text),
(322719,35858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el barbero ha dicho que la barba del anciano es ... que esa.'::text,'más espesa'::text,'más espesa'::text,'la más espesa'::text,'Tía, el barbero ha dicho que la barba del anciano es más espesa que esa.'::text),
(322718,35858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, le barbier a dit que la barbe du vieil homme est ... que celle-là.'::text,'plus épaisse'::text,'plus épaisse'::text,'la plus épaisse'::text,'Ma belle, le barbier a dit que la barbe du vieil homme est plus épaisse que celle-là.'::text),
(322721,35858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, berber yaşlı adamın sakalının ondan ... olduğunu söyledi.'::text,'daha gür'::text,'daha gür'::text,'en gür'::text,'Kızım, berber yaşlı adamın sakalının ondan daha gür olduğunu söyledi.'::text),
(322722,35858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a borbély azt mondta, hogy az öregember szakálla ... annál.'::text,'dúsabb'::text,'dúsabb'::text,'legdúsabb'::text,'Csajszi, a borbély azt mondta, hogy az öregember szakálla dúsabb annál.'::text),
(322725,35859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich kenne die Regel des Barbiers: Dichte Bärte ... zuerst einen Kamm bekommen.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Hör zu, ich kenne die Regel des Barbiers: Dichte Bärte müssen zuerst einen Kamm bekommen.'::text),
(322729,35859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула правило барбера: густі бороди ... спершу отримати гребінець.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Слухай, я чула правило барбера: густі бороди мають спершу отримати гребінець.'::text),
(322728,35859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me he enterado de la regla del barbero: las barbas espesas ... pasar primero por el peine.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Oye, me he enterado de la regla del barbero: las barbas espesas tienen que pasar primero por el peine.'::text),
(322727,35859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu la règle du barbier : les barbes épaisses ... d''abord passer au peigne.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Écoute, j''ai entendu la règle du barbier : les barbes épaisses doivent d''abord passer au peigne.'::text),
(322730,35859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, berberin kuralını duydum: gür sakallar önce tarağa ...'::text,'girmek zorunda'::text,'girmeli'::text,'girmeli'::text,'Dinle, berberin kuralını duydum: gür sakallar önce tarağa girmek zorunda.'::text),
(322731,35859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, hallottam a borbély szabályát: a dús szakállakat először ki ... fésülni.'::text,'kell'::text,'kell'::text,'kellene'::text,'Figyelj, hallottam a borbély szabályát: a dús szakállakat először ki kell fésülni.'::text),
(322734,35860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend hat er seinen dichten Bart sehr ... hochgehalten.'::text,'stolz'::text,'stolz'::text,'Stolz'::text,'Bestie, anscheinend hat er seinen dichten Bart sehr stolz hochgehalten.'::text),
(322738,35860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, він дуже ... підняв свою густу бороду.'::text,'гордо'::text,'гордий'::text,'гордість'::text,'Подружко, кажуть, він дуже гордо підняв свою густу бороду.'::text),
(322737,35860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer levantó su barba espesa muy ...'::text,'orgullosamente'::text,'orgulloso'::text,'orgullo'::text,'Tía, al parecer levantó su barba espesa muy orgullosamente.'::text),
(322736,35860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment il a levé sa barbe épaisse très ...'::text,'fièrement'::text,'fier'::text,'fierté'::text,'Ma belle, apparemment il a levé sa barbe épaisse très fièrement.'::text),
(322739,35860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, anlaşılan gür sakalını çok ... havaya kaldırmış.'::text,'gururla'::text,'gururlu'::text,'gurur'::text,'Kankam, anlaşılan gür sakalını çok gururla havaya kaldırmış.'::text),
(322740,35860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag nagyon ... emelte fel a dús szakállát.'::text,'büszkén'::text,'büszke'::text,'büszkeség'::text,'Csajszi, állítólag nagyon büszkén emelte fel a dús szakállát.'::text),
(310449,34495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Typ ... viele Poster an seiner Wand.'::text,'hat'::text,'haben'::text,'hat'::text,'Der Typ hat viele Poster an seiner Wand.'::text),
(310453,34495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець ... багато постерів на стіні.'::text,'має'::text,'мати'::text,'має'::text,'Хлопець має багато постерів на стіні.'::text),
(310452,34495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chaval ... muchos pósters en su pared.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El chaval tiene muchos pósters en su pared.'::text),
(310451,34495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gars ... plein d''affiches sur son mur.'::text,'a'::text,'ont'::text,'a'::text,'Le gars a plein d''affiches sur son mur.'::text),
(310454,34495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuğun duvarında bir sürü poster ...'::text,'var'::text,'var'::text,'var'::text,'Çocuğun duvarında bir sürü poster var.'::text),
(310455,34495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A srácnak sok plakátja ... a falán.'::text,'van'::text,'van'::text,'van'::text,'A srácnak sok plakátja van a falán.'::text),
(310458,34496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'An der Wand des ersten Schlafzimmers hängen zwanzig ...'::text,'Poster.'::text,'Poster.'::text,'Poster.'::text,'An der Wand des ersten Schlafzimmers hängen zwanzig Poster.'::text),
(310462,34496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На стіні першої спальні двадцять ...'::text,'постерів.'::text,'постер.'::text,'постерів.'::text,'На стіні першої спальні двадцять постерів.'::text),
(310461,34496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pared del primer dormitorio tiene veinte ...'::text,'pósters.'::text,'póster.'::text,'pósters.'::text,'La pared del primer dormitorio tiene veinte pósters.'::text),
(310460,34496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mur de la première chambre a vingt ...'::text,'affiches.'::text,'affiche.'::text,'affiches.'::text,'Le mur de la première chambre a vingt affiches.'::text),
(310463,34496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk yatak odasının duvarında yirmi ... var.'::text,'poster'::text,'poster'::text,'posterler'::text,'İlk yatak odasının duvarında yirmi poster var.'::text),
(310464,34496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az első hálószoba falán húsz ... van.'::text,'plakát'::text,'plakát'::text,'plakát'::text,'Az első hálószoba falán húsz plakát van.'::text),
(310467,34497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, das ist kein Gemälde, das ist ... Poster.'::text,'ein'::text,'ein'::text,'das'::text,'Nee Bro, das ist kein Gemälde, das ist ein Poster.'::text),
(310471,34497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, це не картина, це ... постер.'::text,''::text,NULL::text,NULL::text,'Не, бро, це не картина, це постер.'::text),
(310470,34497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, no es un cuadro, es ... póster.'::text,'un'::text,'un'::text,'el'::text,'Qué va, tío, no es un cuadro, es un póster.'::text),
(310469,34497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, c''est pas un tableau, c''est ... poster.'::text,'un'::text,'un'::text,'le'::text,'Non frère, c''est pas un tableau, c''est un poster.'::text),
(310472,34497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bu bir tablo değil, ... poster.'::text,'bir'::text,'bir'::text,NULL::text,'Yok kanka, bu bir tablo değil, bir poster.'::text),
