(299437,33271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його друг сьогодні — ... велика допомога.'::text,''::text,NULL::text,NULL::text,'Його друг сьогодні — велика допомога.'::text),
(299436,33271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su amigo es hoy ... gran ayuda.'::text,'una'::text,'una'::text,'la'::text,'Su amigo es hoy una gran ayuda.'::text),
(299435,33271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son ami est ... grande aide aujourd''hui.'::text,'une'::text,'une'::text,'la'::text,'Son ami est une grande aide aujourd''hui.'::text),
(299438,33271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı bugün ... büyük yardım oluyor.'::text,'bir'::text,'bir'::text,NULL::text,'Arkadaşı bugün bir büyük yardım oluyor.'::text),
(299439,33271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátja ma ... nagy segítség.'::text,'egy'::text,'egy'::text,'a'::text,'A barátja ma egy nagy segítség.'::text),
(299442,33272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, nimm ... zur Hilfe.'::text,'diese Taschentücher'::text,'dieses Taschentuch'::text,'jene Taschentücher'::text,'Hier, nimm diese Taschentücher zur Hilfe.'::text),
(299446,33272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ось, візьми ... на допомогу.'::text,'ці серветки'::text,'ці серветки'::text,'ту серветку'::text,'Ось, візьми ці серветки на допомогу.'::text),
(299445,33272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toma, coge ... para ayudarte.'::text,'estos pañuelos'::text,'este pañuelo'::text,'esos pañuelos'::text,'Toma, coge estos pañuelos para ayudarte.'::text),
(299444,33272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiens, prends ... pour t''aider.'::text,'ces mouchoirs'::text,'ce mouchoir'::text,'ces mouchoirs'::text,'Tiens, prends ces mouchoirs pour t''aider.'::text),
(299447,33272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buyur, yardım olsun diye ... al.'::text,'bu mendilleri'::text,'bu mendilleri'::text,'şu mendili'::text,'Buyur, yardım olsun diye bu mendilleri al.'::text),
(299448,33272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tessék, fogd ... segítségül.'::text,'ezeket a zsebkendőket'::text,'ezt a zsebkendőt'::text,'azokat a zsebkendőket'::text,'Tessék, fogd ezeket a zsebkendőket segítségül.'::text),
(299451,33273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, deine Nase blutet, du brauchst ... Hilfe, echt.'::text,'etwas'::text,'viele'::text,'ein paar'::text,'Alter, deine Nase blutet, du brauchst etwas Hilfe, echt.'::text),
(299455,33273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у тебе кров з носа, тобі потрібна ... допомога, реально.'::text,'якась'::text,'багато'::text,'кілька'::text,'Бро, у тебе кров з носа, тобі потрібна якась допомога, реально.'::text),
(299454,33273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, te sangra la nariz, necesitas ... ayuda, en serio.'::text,'algo de'::text,'muchas'::text,'unas pocas'::text,'Tío, te sangra la nariz, necesitas algo de ayuda, en serio.'::text),
(299453,33273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ton nez saigne, il te faut ... aide, sérieux.'::text,'de l'''::text,'beaucoup d'''::text,'quelques'::text,'Frère, ton nez saigne, il te faut de l'' aide, sérieux.'::text),
(299456,33273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, burnun kanıyor, ... yardıma ihtiyacın var, cidden.'::text,'biraz'::text,'çok'::text,'birkaç'::text,'Kanka, burnun kanıyor, biraz yardıma ihtiyacın var, cidden.'::text),
(299457,33273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, vérzik az orrod, ... segítség kell, komolyan.'::text,'némi'::text,'sok'::text,'pár'::text,'Tesó, vérzik az orrod, némi segítség kell, komolyan.'::text),
(299073,33231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich mag deinen Smoothie, er ... so gesund. Respekt.'::text,'ist'::text,'sind'::text,'bin'::text,'Ich mag deinen Smoothie, er ist so gesund. Respekt.'::text),
(299077,33231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мені подобається твій смузі, він ... такий корисний. Респект.'::text,'є'::text,'є'::text,'є'::text,'Мені подобається твій смузі, він є такий корисний. Респект.'::text),
(299076,33231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me gusta tu smoothie, ... muy saludable. Chapó.'::text,'es'::text,'son'::text,'soy'::text,'Me gusta tu smoothie, es muy saludable. Chapó.'::text),
(299075,33231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'J''aime bien ton smoothie, il ... tellement sain. Respect.'::text,'est'::text,'sont'::text,'suis'::text,'J''aime bien ton smoothie, il est tellement sain. Respect.'::text),
(299078,33231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Smoothie''ni sevdim, çok sağlıklı ...! Saygılar.'::text,''::text,NULL::text,NULL::text,'Smoothie''ni sevdim, çok sağlıklı! Saygılar.'::text),
(299079,33231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tetszik a smoothie-d, olyan egészséges ...! Le a kalappal.'::text,''::text,NULL::text,'vagyok'::text,'Tetszik a smoothie-d, olyan egészséges! Le a kalappal.'::text),
(299091,33233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... er einen gesunden Smoothie mit Mango und Spinat.'::text,'machte'::text,'machte'::text,'macht'::text,'Heute Morgen machte er einen gesunden Smoothie mit Mango und Spinat.'::text),
(299095,33233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці він ... корисний смузі з манго і шпинатом.'::text,'зробив'::text,'зробив'::text,'робить'::text,'Сьогодні вранці він зробив корисний смузі з манго і шпинатом.'::text),
(299094,33233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana ... un smoothie saludable con mango y espinacas.'::text,'ha preparado'::text,'ha preparado'::text,'prepara'::text,'Esta mañana ha preparado un smoothie saludable con mango y espinacas.'::text),
(299093,33233,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, il ... un smoothie sain à la mangue et aux épinards.'::text,'a fait'::text,'a fait'::text,'fait'::text,'Ce matin, il a fait un smoothie sain à la mangue et aux épinards.'::text),
(299096,33233,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah mango ve ıspanaklı sağlıklı bir smoothie ...'::text,'yaptı'::text,'yaptı'::text,'yapar'::text,'Bu sabah mango ve ıspanaklı sağlıklı bir smoothie yaptı.'::text),
