(299100,33234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, jetzt ist er gesund, aber gestern ... er Pizza.'::text,'aß'::text,'isst'::text,NULL::text,'Nee Bro, jetzt ist er gesund, aber gestern aß er Pizza.'::text),
