(299103,33234,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, ahora está sano, pero ayer ... pizza.'::text,'comió'::text,'come'::text,NULL::text,'Qué va, tío, ahora está sano, pero ayer comió pizza.'::text),
(299102,33234,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, maintenant il est en mode healthy, mais hier il ... de la pizza.'::text,'a mangé'::text,'mange'::text,NULL::text,'Non frère, maintenant il est en mode healthy, mais hier il a mangé de la pizza.'::text),
(299105,33234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, şimdi sağlıklı ama dün pizza ...'::text,'yedi'::text,'yer'::text,NULL::text,'Yok kanka, şimdi sağlıklı ama dün pizza yedi.'::text),
